import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Skeleton } from '@/components/ui/Skeleton';

// Hooks
import { useMediaQuery } from '@/hooks/useMediaQuery';
import { useDebounce } from '@/hooks/useDebounce';

// Services
import { blogApi, type BlogPost } from '@/services/blogApi';

// ============================================================
// BLOGS PAGE
// ============================================================
export default function BlogsPage() {
  const isMobile = useMediaQuery('(max-width: 768px)');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [currentPage, setCurrentPage] = useState(1);
  const postsPerPage = 6;

  const debouncedSearch = useDebounce(searchQuery, 300);

  // Fetch all blog posts (you can add server-side pagination later)
  const { data: allPosts, isLoading, error } = useQuery<BlogPost[], Error>({
    queryKey: ['blogs'],
    queryFn: blogApi.getAll,
  });

  // Get unique categories from posts
  const categories = allPosts
    ? ['all', ...new Set(allPosts.map((post: BlogPost) => post.category))]
    : ['all'];

  // Filter posts based on search and category
  const filteredPosts = allPosts?.filter((post: BlogPost) => {
    const matchesSearch = post.title.toLowerCase().includes(debouncedSearch.toLowerCase()) ||
                          post.excerpt.toLowerCase().includes(debouncedSearch.toLowerCase());
    const matchesCategory = selectedCategory === 'all' || post.category === selectedCategory;
    return matchesSearch && matchesCategory;
  }) || [];

  // Pagination
  const totalPages = Math.ceil(filteredPosts.length / postsPerPage);
  const paginatedPosts = filteredPosts.slice(
    (currentPage - 1) * postsPerPage,
    currentPage * postsPerPage
  );

  // Reset page when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [debouncedSearch, selectedCategory]);

  // Loading state
  if (isLoading) {
    return <BlogsSkeleton />;
  }

  // Error state
  if (error || !allPosts) {
    return (
      <Container className="py-20 text-center">
        <h2 className="font-cinzel text-2xl text-brown">Unable to load blog posts</h2>
        <p className="text-brown-light mt-2">Please try again later.</p>
        <button
          onClick={() => window.location.reload()}
          className="btn-gold inline-block mt-6"
        >
          Retry
        </button>
      </Container>
    );
  }

  // Empty state
  if (filteredPosts.length === 0) {
    return (
      <Container className="py-20 text-center">
        <h2 className="font-cinzel text-2xl text-brown">No blog posts found</h2>
        <p className="text-brown-light mt-2">Try adjusting your search or category filter.</p>
        <button
          onClick={() => { setSearchQuery(''); setSelectedCategory('all'); }}
          className="btn-gold inline-block mt-6"
        >
          Clear Filters
        </button>
      </Container>
    );
  }

  return (
    <Container className="py-12 md:py-20">
      {/* Page header */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="text-center mb-12"
      >
        <div className="ornate-divider">
          <span className="diamond">Γ£ª</span>
        </div>
        <h1 className="font-cinzel text-4xl md:text-5xl font-bold text-brown">
          Divine Insights
        </h1>
        <p className="text-brown-light mt-3 max-w-2xl mx-auto">
          Stories, wisdom, and behind-the-scenes from the world of handcrafted murtis.
        </p>
      </motion.div>

      {/* Search and filter bar */}
      <div className="flex flex-col md:flex-row md:items-center gap-4 mb-10">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-brown-light" />
          <Input
            type="text"
            placeholder="Search articles..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9 pr-4 py-2.5 bg-white border-gold/10 rounded-full focus:border-gold"
          />
        </div>
        <div className="flex flex-wrap gap-2 overflow-x-auto pb-2">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all whitespace-nowrap ${
                selectedCategory === cat
                  ? 'bg-gold text-white shadow-gold'
                  : 'bg-white text-brown-light hover:bg-gold/10 border border-gold/10'
              }`}
            >
              {cat === 'all' ? 'All' : cat}
            </button>
          ))}
        </div>
      </div>

      {/* Blog grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
        {paginatedPosts.map((post: BlogPost, index: number) => (
          <motion.article
            key={post.id}
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4, delay: index * 0.05 }}
            whileHover={{ y: -6 }}
            className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gold/5 hover:shadow-xl transition-all duration-300 group"
          >
            <Link href={`/blogs/${post.slug}`} className="block">
              <div className="relative aspect-[16/9] bg-sand overflow-hidden">
                <Image
                  src={post.coverImage}
                  alt={post.title}
                  fill
                  className="object-cover transition-transform duration-700 group-hover:scale-105"
                  sizes="(max-width: 768px) 100vw, (max-width: 1024px) 50vw, 33vw"
                />
                <div className="absolute top-3 left-3 bg-white/90 backdrop-blur text-xs font-medium px-2.5 py-1 rounded-full">
                  {post.category}
                </div>
              </div>
              <div className="p-5">
                <h2 className="font-cinzel text-xl font-bold text-brown group-hover:text-gold-dark transition-colors line-clamp-2">
                  {post.title}
                </h2>
                <p className="text-brown-light text-sm mt-2 line-clamp-3">
                  {post.excerpt}
                </p>
                <div className="flex items-center justify-between mt-4 text-xs text-brown-light/70">
                  <div className="flex items-center gap-3">
                    <span className="flex items-center gap-1">
                      <User className="w-3 h-3" />
                      {post.author}
                    </span>
                    <span className="flex items-center gap-1">
                      <Calendar className="w-3 h-3" />
                      {format(new Date(post.publishedAt), 'MMM d, yyyy')}
                    </span>
                  </div>
                  <span>{post.readTime} min read</span>
                </div>
                {post.tags && post.tags.length > 0 && (
                  <div className="flex flex-wrap gap-1 mt-3">
                    {post.tags.slice(0, 2).map((tag) => (
                      <span key={tag} className="text-xs bg-sand/50 px-2 py-0.5 rounded-full text-brown-light">
                        #{tag}
                      </span>
                    ))}
                    {post.tags.length > 2 && (
                      <span className="text-xs text-brown-light/50">+{post.tags.length - 2}</span>
                    )}
                  </div>
                )}
              </div>
            </Link>
          </motion.article>
        ))}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2 mt-12">
          <button
            onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className={`p-2 rounded-lg border border-gold/10 transition-colors ${
              currentPage === 1
                ? 'opacity-40 cursor-not-allowed'
                : 'hover:bg-gold/10'
            }`}
            aria-label="Previous page"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>
          {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
            <button
              key={page}
              onClick={() => setCurrentPage(page)}
              className={`w-10 h-10 rounded-lg font-medium transition-colors ${
                page === currentPage
                  ? 'bg-gold text-white'
                  : 'hover:bg-gold/10 text-brown'
              }`}
            >
              {page}
            </button>
          ))}
          <button
            onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className={`p-2 rounded-lg border border-gold/10 transition-colors ${
              currentPage === totalPages
                ? 'opacity-40 cursor-not-allowed'
                : 'hover:bg-gold/10'
            }`}
            aria-label="Next page"
          >
            <ChevronRight className="w-5 h-5" />
          </button>
        </div>
      )}
    </Container>
  );
}

// ============================================================
// SKELETON LOADER
// ============================================================
function BlogsSkeleton() {
  return (
    <Container className="py-12 md:py-20">
      <div className="text-center mb-12">
        <Skeleton className="h-12 w-64 mx-auto" />
        <Skeleton className="h-6 w-96 mx-auto mt-3" />
      </div>
      <div className="flex flex-col md:flex-row gap-4 mb-10">
        <Skeleton className="h-12 flex-1 rounded-full" />
        <div className="flex gap-2">
          {Array.from({ length: 4 }).map((_, i) => (
            <Skeleton key={i} className="h-10 w-20 rounded-full" />
          ))}
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {Array.from({ length: 6 }).map((_, i) => (
          <div key={i} className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gold/5">
            <Skeleton className="aspect-[16/9] w-full" />
            <div className="p-5 space-y-3">
              <Skeleton className="h-6 w-3/4" />
              <Skeleton className="h-4 w-full" />
              <Skeleton className="h-4 w-2/3" />
              <div className="flex justify-between">
                <Skeleton className="h-4 w-24" />
                <Skeleton className="h-4 w-16" />
              </div>
            </div>
          </div>
        ))}
      </div>
    </Container>
  );
}

// frontend/src/app/cart/page.tsx

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { motion, AnimatePresence } from 'framer-motion';
import { useRouter } from 'next/navigation';
import { toast } from 'react-hot-toast';
import {
  ShoppingBag,
  Trash2,
  Minus,
  Plus,
  ChevronRight,
  Ticket,
  X,
  Gift,
  Truck,
  Shield,
} from 'lucide-react';

import { Container } from '@/components/ui/Container';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Skeleton } from '@/components/ui/Skeleton';

import { useCart } from '@/features/cart/hooks/useCart';
import { formatPrice } from '@/lib/utils';

// ============================================================
// Cart Page
// ============================================================
export default function CartPage() {
  const router = useRouter();
  const {
    items,
    totalItems,
    subtotal: totalPrice,
    updateQuantity,
    removeItem,
    clearCart,
  } = useCart();

  const [couponCode, setCouponCode] = useState('');
  const [appliedCoupon, setAppliedCoupon] = useState<{
    code: string;
    discount: number;
  } | null>(null);
  const [isApplyingCoupon, setIsApplyingCoupon] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  // Shipping & tax calculations (mock)
  const shipping = totalPrice > 5000 ? 0 : 299;
  const tax = Math.round(totalPrice * 0.18); // 18% GST
  const discount = appliedCoupon
    ? Math.round(totalPrice * (appliedCoupon.discount / 100))
    : 0;
  const grandTotal = totalPrice + shipping + tax - discount;

  // Apply coupon handler
  const handleApplyCoupon = async () => {
    if (!couponCode.trim()) {
      toast.error('Please enter a coupon code');
      return;
    }

    setIsApplyingCoupon(true);
    // Simulate API call
    await new Promise((resolve) => setTimeout(resolve, 1000));

    // Mock coupon validation (you'd check against your backend)
    if (couponCode.toUpperCase() === 'DIVINE10') {
      setAppliedCoupon({ code: couponCode.toUpperCase(), discount: 10 });
      toast.success('Coupon applied! 10% discount Γ£¿');
      setCouponCode('');
    } else if (couponCode.toUpperCase() === 'WELCOME20') {
      setAppliedCoupon({ code: couponCode.toUpperCase(), discount: 20 });
      toast.success('Coupon applied! 20% discount ≡ƒÖÅ');
      setCouponCode('');
    } else {
      toast.error('Invalid coupon code');
    }
    setIsApplyingCoupon(false);
  };

  // Remove coupon
  const removeCoupon = () => {
    setAppliedCoupon(null);
    toast.success('Coupon removed');
  };

  // Checkout handler
  const handleCheckout = () => {
    if (items.length === 0) {
      toast.error('Your cart is empty');
      return;
    }
    router.push('/checkout');
  };

  // Loading state (while cart is being hydrated from store)
  if (isLoading) {
    return <CartSkeleton />;
  }

  // Empty cart state
  if (items.length === 0) {
    return (
      <Container className="py-12 md:py-20">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center max-w-md mx-auto"
        >
          <div className="w-24 h-24 mx-auto bg-gold/10 rounded-full flex items-center justify-center mb-6">
            <ShoppingBag className="w-12 h-12 text-gold" />
          </div>
          <h1 className="font-cinzel text-2xl md:text-3xl font-bold text-brown">
            Your Cart is Empty
          </h1>
          <p className="text-brown-light mt-2">
            Looks like you haven't added any divine murtis yet.
          </p>
          <Link href="/products" className="btn-gold inline-block mt-6">
            Browse Collection
          </Link>
        </motion.div>
      </Container>
    );
  }

  return (
    <Container className="py-8 md:py-12">
      {/* Page header */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="mb-8"
      >
        <div className="flex items-center gap-3">
          <h1 className="font-cinzel text-2xl md:text-3xl font-bold text-brown">
            Your Cart
          </h1>
          <span className="text-sm text-brown-light bg-sand/60 px-3 py-1 rounded-full">
            {totalItems} {totalItems === 1 ? 'item' : 'items'}
          </span>
        </div>
        <p className="text-brown-light text-sm mt-1">
          Review your selection and proceed to checkout.
        </p>
      </motion.div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Left: Cart Items */}
        <div className="lg:col-span-2 space-y-4">
          <AnimatePresence mode="popLayout">
            {items.map((item, index) => (
              <motion.div
                key={item.product.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                transition={{ duration: 0.3, delay: index * 0.05 }}
                className="bg-white rounded-2xl p-4 md:p-6 shadow-sm border border-gold/5 hover:shadow-md transition-shadow"
              >
                <div className="flex gap-4">
                  {/* Product Image */}
                  <Link
                    href={`/products/${item.product.slug}`}
                    className="relative w-24 h-24 md:w-28 md:h-28 rounded-xl overflow-hidden bg-sand flex-shrink-0"
                  >
                    <Image
                      src={item.product.images[0] || '/placeholder.png'}
                      alt={item.product.name}
                      fill
                      className="object-cover"
                      sizes="(max-width: 768px) 96px, 112px"
                    />
                    {item.product.discount && (
                      <span className="absolute top-1 left-1 bg-maroon text-white text-xs font-bold px-1.5 py-0.5 rounded">
                        -{item.product.discount}%
                      </span>
                    )}
                  </Link>

                  {/* Product Info */}
                  <div className="flex-1 min-w-0">
                    <Link
                      href={`/products/${item.product.slug}`}
                      className="font-cinzel font-semibold text-brown hover:text-gold-dark transition-colors line-clamp-1"
                    >
                      {item.product.name}
                    </Link>
                    <p className="text-sm text-brown-light/70">
                      {item.product.material || 'Handcrafted'}
                    </p>
                    <div className="flex items-center gap-3 mt-1">
                      <span className="font-cinzel text-lg text-gold-dark">
                        Γé╣{formatPrice(item.product.price)}
                      </span>
                      {item.product.originalPrice && (
                        <span className="text-xs text-brown-light line-through">
                          Γé╣{formatPrice(item.product.originalPrice)}
                        </span>
                      )}
                    </div>

                    {/* Quantity and Remove */}
                    <div className="flex items-center gap-3 mt-3">
                      <div className="flex items-center border border-gold/20 rounded-full overflow-hidden">
                        <button
                          onClick={() =>
                            updateQuantity(item.product.id, item.quantity - 1)
                          }
                          className="px-3 py-1.5 hover:bg-gold/10 transition-colors"
                          aria-label="Decrease quantity"
                        >
                          <Minus className="w-3.5 h-3.5" />
                        </button>
                        <span className="w-8 text-center text-sm font-medium">
                          {item.quantity}
                        </span>
                        <button
                          onClick={() =>
                            updateQuantity(item.product.id, item.quantity + 1)
                          }
                          className="px-3 py-1.5 hover:bg-gold/10 transition-colors"
                          aria-label="Increase quantity"
                        >
                          <Plus className="w-3.5 h-3.5" />
                        </button>
                      </div>
                      <button
                        onClick={() => removeItem(item.product.id)}
                        className="text-brown-light hover:text-red-500 transition-colors p-1"
                        aria-label="Remove item"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>

                  {/* Subtotal (desktop) */}
                  <div className="hidden md:flex flex-col items-end justify-between">
                    <span className="font-cinzel text-sm font-medium text-brown">
                      Γé╣{formatPrice(item.product.price * item.quantity)}
                    </span>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>

          {/* Continue shopping */}
          <Link
            href="/products"
            className="inline-flex items-center gap-2 text-sm text-brown-light hover:text-gold-dark transition-colors"
          >
            <ChevronRight className="w-4 h-4" />
            Continue Shopping
          </Link>
        </div>

        {/* Right: Order Summary */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.1 }}
          className="lg:col-span-1"
        >
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-gold/5 sticky top-24">
            <h2 className="font-cinzel text-xl font-bold text-brown mb-6">
              Order Summary
            </h2>

            {/* Coupon Section */}
            <div className="mb-6">
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Ticket className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-brown-light" />
                  <Input
                    type="text"
                    placeholder="Coupon code"
                    value={couponCode}
                    onChange={(e) => setCouponCode(e.target.value.toUpperCase())}
                    disabled={!!appliedCoupon}
                    className="pl-9 pr-4 py-2 text-sm border-gold/10 rounded-full"
                  />
                </div>
                <Button
                  onClick={handleApplyCoupon}
                  disabled={!!appliedCoupon || isApplyingCoupon}
                  className="btn-gold px-4 py-2 text-sm whitespace-nowrap"
                >
                  {isApplyingCoupon ? 'Applying...' : 'Apply'}
                </Button>
              </div>

              {appliedCoupon && (
                <div className="mt-2 flex items-center justify-between bg-green-50/70 rounded-lg px-3 py-1.5 border border-green-200">
                  <span className="text-sm text-green-700">
                    Coupon {appliedCoupon.code} applied
                    <span className="text-xs ml-1">(-{appliedCoupon.discount}%)</span>
                  </span>
                  <button
                    onClick={removeCoupon}
                    className="text-green-700/60 hover:text-red-500 transition-colors"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              )}
            </div>

            {/* Price Breakdown */}
            <div className="space-y-3 text-sm">
              <div className="flex justify-between">
                <span className="text-brown-light">Subtotal</span>
                <span className="font-medium text-brown">
                  Γé╣{formatPrice(totalPrice)}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-brown-light">Shipping</span>
                <span className="font-medium text-brown">
                  {shipping === 0 ? 'Free' : `Γé╣${formatPrice(shipping)}`}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-brown-light">Tax (GST 18%)</span>
                <span className="font-medium text-brown">
                  Γé╣{formatPrice(tax)}
                </span>
              </div>
              {appliedCoupon && (
                <div className="flex justify-between text-green-600">
                  <span>Discount ({appliedCoupon.discount}%)</span>
                  <span>-Γé╣{formatPrice(discount)}</span>
                </div>
              )}
            </div>

            <div className="border-t border-gold/10 my-4 pt-4">
              <div className="flex justify-between text-lg font-semibold">
                <span className="font-cinzel text-brown">Total</span>
                <span className="font-cinzel text-gold-dark">
                  Γé╣{formatPrice(grandTotal)}
                </span>
              </div>
              <p className="text-xs text-brown-light/70 mt-1">
                Inclusive of all taxes
              </p>
            </div>

            {/* Checkout Button */}
            <Button
              onClick={handleCheckout}
              className="btn-gold w-full py-3.5 text-base"
            >
              Proceed to Checkout
              <ChevronRight className="w-5 h-5 ml-1" />
            </Button>

            {/* Trust badges */}
            <div className="mt-6 grid grid-cols-2 gap-2 text-xs text-brown-light/60">
              <div className="flex items-center gap-1.5">
                <Shield className="w-3.5 h-3.5 text-gold" />
                <span>Secure Checkout</span>
              </div>
              <div className="flex items-center gap-1.5">
                <Truck className="w-3.5 h-3.5 text-gold" />
                <span>Free Shipping over Γé╣5,000</span>
              </div>
              <div className="flex items-center gap-1.5 col-span-2">
                <Gift className="w-3.5 h-3.5 text-gold" />
                <span>Each murti comes with a blessing certificate</span>
              </div>
            </div>
          </div>
        </motion.div>
      </div>
    </Container>
  );
}

// ============================================================
// SKELETON LOADER
// ============================================================
function CartSkeleton() {
  return (
    <Container className="py-12 md:py-20">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-4">
          {Array.from({ length: 2 }).map((_, i) => (
            <div key={i} className="bg-white rounded-2xl p-4 md:p-6 shadow-sm border border-gold/5">
              <div className="flex gap-4">
                <Skeleton className="w-24 h-24 rounded-xl" />
                <div className="flex-1 space-y-2">
                  <Skeleton className="h-5 w-3/4" />
                  <Skeleton className="h-4 w-1/3" />
                  <Skeleton className="h-6 w-1/4" />
                  <div className="flex gap-3">
                    <Skeleton className="h-8 w-24 rounded-full" />
                    <Skeleton className="h-8 w-8 rounded-full" />
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
        <div>
          <div className="bg-white rounded-2xl p-6 shadow-sm border border-gold/5">
            <Skeleton className="h-6 w-1/2 mb-6" />
            <div className="space-y-3">
              <Skeleton className="h-10 w-full rounded-full" />
              <div className="space-y-2">
                {Array.from({ length: 3 }).map((_, i) => (
                  <Skeleton key={i} className="h-5 w-full" />
                ))}
              </div>
              <Skeleton className="h-8 w-3/4 mx-auto mt-4" />
              <Skeleton className="h-12 w-full rounded-full" />
            </div>
          </div>
        </div>
      </div>
    </Container>
  );
}

// frontend/src/app/categories/page.tsx

'use client';

import Link from 'next/link';
import Image from 'next/image';
import { motion } from 'framer-motion';
import { useQuery } from '@tanstack/react-query';
import type { Category } from '@/features/categories/types/category.types';
import { Container } from '@/components/ui/Container';
import { Skeleton } from '@/components/ui/Skeleton';
import { categoriesApi } from '@/features/categories/api/categoriesApi';
import { useMediaQuery } from '@/hooks/useMediaQuery';

// ============================================================
// CATEGORIES PAGE
// ============================================================
export default function CategoriesPage() {
  const isMobile = useMediaQuery('(max-width: 768px)');
  
  // Fetch categories
  const { data, isLoading, error } = useQuery({
    queryKey: ['categories'],
    queryFn: () => categoriesApi.getCategories(),
  });

  const categories = data?.categories;

  // Loading state
  if (isLoading) {
    return (
      <Container className="py-12 md:py-20">
        <div className="text-center mb-12">
          <h1 className="font-cinzel text-4xl md:text-5xl font-bold text-brown">Browse by Deity</h1>
          <p className="text-brown-light mt-3 max-w-2xl mx-auto">
            Explore our collection of handcrafted murtis, each dedicated to a divine form.
          </p>
        </div>
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
          {Array.from({ length: 8 }).map((_, i) => (
            <Skeleton key={i} className="aspect-square rounded-2xl" />
          ))}
        </div>
      </Container>
    );
  }

  // Error state
  if (error || !categories) {
    return (
      <Container className="py-20 text-center">
        <h2 className="font-cinzel text-2xl text-brown">Unable to load categories</h2>
        <p className="text-brown-light mt-2">Please try again later.</p>
        <button
          onClick={() => window.location.reload()}
          className="btn-gold inline-block mt-6"
        >
          Retry
        </button>
      </Container>
    );
  }

  // Group categories by first letter for optional alphabet navigation
  const groupedCategories = categories.reduce((acc: Record<string, Category[]>, cat: Category) => {
    const letter = cat.name.charAt(0).toUpperCase();
    if (!acc[letter]) acc[letter] = [];
    acc[letter].push(cat);
    return acc;
  }, {});

  return (
    <Container className="py-12 md:py-20">
      {/* Page header */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="text-center mb-12"
      >
        <div className="ornate-divider">
          <span className="diamond">Γ£ª</span>
        </div>
        <h1 className="font-cinzel text-4xl md:text-5xl font-bold text-brown">
          Browse by Deity
        </h1>
        <p className="text-brown-light mt-3 max-w-2xl mx-auto">
          Choose from our collection of divine forms, each crafted with precision and devotion.
        </p>
        <div className="mt-6 text-sm text-brown-light/60">
          {categories.length} categories available
        </div>
      </motion.div>

      {/* Category grid */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
        {categories.map((category: Category, index: number) => (
          <motion.div
            key={category.id}
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4, delay: index * 0.05 }}
            whileHover={{ y: -8 }}
            className="group"
          >
            <Link
              href={`/products?category=${category.id}`}
              className="block bg-white rounded-2xl overflow-hidden shadow-sm border border-gold/5 hover:shadow-xl transition-all duration-300"
            >
              <div className="relative aspect-square bg-sand overflow-hidden">
                {category.image ? (
                  <Image
                    src={category.image}
                    alt={category.name}
                    fill
                    className="object-cover transition-transform duration-700 group-hover:scale-105"
                    sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-6xl opacity-20">
                    ≡ƒòë∩╕Å
                  </div>
                )}
                {/* Gradient overlay on hover */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                {/* Product count badge */}
                {category.productCount !== undefined && (
                  <div className="absolute bottom-3 left-3 bg-white/90 backdrop-blur text-xs font-medium px-2.5 py-1 rounded-full shadow-sm">
                    {category.productCount} murtis
                  </div>
                )}
              </div>
              <div className="p-4 text-center">
                <h3 className="font-cinzel text-base md:text-lg font-semibold text-brown group-hover:text-gold-dark transition-colors">
                  {category.name}
                </h3>
                <p className="text-xs text-brown-light/60 mt-1">
                  {category.description || 'Divine collection'}
                </p>
              </div>
            </Link>
          </motion.div>
        ))}
      </div>

      {/* Empty state (just in case) */}
      {categories.length === 0 && (
        <div className="text-center py-16">
          <p className="text-brown-light">No categories available at the moment.</p>
        </div>
      )}

      {/* Optional: Alphabet navigation (if many categories) */}
      {Object.keys(groupedCategories).length > 1 && (
        <div className="mt-12 flex flex-wrap justify-center gap-2">
          {Object.keys(groupedCategories).sort().map((letter) => (
            <a
              key={letter}
              href={`#category-${letter}`}
              className="w-8 h-8 flex items-center justify-center rounded-full text-sm font-medium text-brown-light hover:bg-gold hover:text-white transition-colors"
            >
              {letter}
            </a>
          ))}
        </div>
      )}

      {/* Alphabet sections */}
      {Object.entries(groupedCategories)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([letter, cats]) => (
          <section key={letter} id={`category-${letter}`} className="mt-16">
            <h2 className="font-cinzel text-2xl font-bold text-brown border-b border-gold/10 pb-3 mb-6">
              {letter}
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
              {cats.map((category: Category) => (
                <motion.div
                  key={category.id}
                  initial={{ opacity: 0, scale: 0.95 }}
                  whileInView={{ opacity: 1, scale: 1 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.3 }}
                  className="group"
                >
                  <Link
                    href={`/products?category=${category.id}`}
                    className="block bg-white rounded-2xl overflow-hidden shadow-sm border border-gold/5 hover:shadow-xl transition-all duration-300"
                  >
                    <div className="relative aspect-square bg-sand overflow-hidden">
                      {category.image ? (
                        <Image
                          src={category.image}
                          alt={category.name}
                          fill
                          className="object-cover transition-transform duration-700 group-hover:scale-105"
                          sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-5xl opacity-10">
                          ≡ƒòë∩╕Å
                        </div>
                      )}
                    </div>
                    <div className="p-3 text-center">
                      <h3 className="font-cinzel text-sm md:text-base font-semibold text-brown group-hover:text-gold-dark transition-colors">
                        {category.name}
                      </h3>
                      {category.productCount !== undefined && (
                        <p className="text-xs text-brown-light/60 mt-0.5">
                          {category.productCount} items
                        </p>
                      )}
                    </div>
                  </Link>
                </motion.div>
              ))}
            </div>
          </section>
        ))}
    </Container>
  );
}

// frontend/src/app/checkout/page.tsx

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import Image from 'next/image';
import { motion, AnimatePresence } from 'framer-motion';
import { useForm, useFieldArray } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { toast } from 'react-hot-toast';
import {
  ChevronLeft,
  ChevronRight,
  Check,
  Truck,
  CreditCard,
  Wallet,
  Building,
  MapPin,
  Phone,
  Mail,
  User,
  Home,
  Lock,
  Clock,
} from 'lucide-react';

import { Container } from '@/components/ui/Container';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Select } from '@/components/ui/Select';

import { useCart } from '@/features/cart/hooks/useCart';
import { useAuth } from '@/features/auth/hooks/useAuth';
import { formatPrice } from '@/lib/utils';

// ============================================================
// Types and Validation Schemas
// ============================================================

// Address schema
const addressSchema = z.object({
  fullName: z.string().min(2, 'Full name is required'),
  email: z.string().email('Invalid email address'),
  phone: z.string().min(10, 'Valid phone number is required'),
  addressLine1: z.string().min(5, 'Address is required'),
  addressLine2: z.string().optional(),
  city: z.string().min(2, 'City is required'),
  state: z.string().min(2, 'State is required'),
  pincode: z.string().min(6, 'Valid pincode is required'),
  country: z.string().default('India'),
});

// Shipping schema
const shippingSchema = z.object({
  shippingMethod: z.enum(['standard', 'express'], {
    error: 'Please select a shipping method',
  }),
});

// Payment schema
const paymentSchema = z.object({
  paymentMethod: z.enum(['cod', 'card', 'upi'], {
    error: 'Please select a payment method',
  }),
  // Card fields (conditional)
  cardNumber: z.string().optional(),
  expiryDate: z.string().optional(),
  cvv: z.string().optional(),
  nameOnCard: z.string().optional(),
  // UPI
  upiId: z.string().optional(),
});

// Combined checkout form schema
const checkoutSchema = z.object({
  address: addressSchema,
  shipping: shippingSchema,
  payment: paymentSchema,
});

type CheckoutFormInput = z.input<typeof checkoutSchema>;
type CheckoutFormData = z.output<typeof checkoutSchema>;

// ============================================================
// Checkout Page
// ============================================================
export default function CheckoutPage() {
  const router = useRouter();
  const { items, subtotal: totalPrice, clearCart } = useCart();
  const { user } = useAuth();
  const [currentStep, setCurrentStep] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [orderComplete, setOrderComplete] = useState(false);
  const [orderId, setOrderId] = useState('');

  const totalSteps = ['Address', 'Shipping', 'Payment', 'Confirm'];

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    formState: { errors, isValid },
    trigger,
  } = useForm<CheckoutFormInput, any, CheckoutFormData>({
    resolver: zodResolver(checkoutSchema),
    defaultValues: {
      address: {
        fullName: user?.name || '',
        email: user?.email || '',
        phone: '',
        addressLine1: '',
        addressLine2: '',
        city: '',
        state: '',
        pincode: '',
        country: 'India',
      },
      shipping: {
        shippingMethod: 'standard',
      },
      payment: {
        paymentMethod: 'cod',
      },
    },
  });

  // Watch payment method to conditionally show fields
  const paymentMethod = watch('payment.paymentMethod');

  // Redirect if cart is empty
  useEffect(() => {
    if (items.length === 0) {
      toast.error('Your cart is empty');
      router.push('/products');
    }
  }, [items, router]);

  // Step validation and navigation
  const goToStep = (step: number) => {
    const stepKeys = ['address', 'shipping', 'payment'] as const;
    if (step > currentStep) {
      // Validate current step before proceeding
      trigger(stepKeys[currentStep]).then((isValid) => {
        if (isValid) {
          setCurrentStep(step);
        } else {
          toast.error('Please fill in all required fields');
        }
      });
    } else {
      setCurrentStep(step);
    }
  };

  const nextStep = () => {
    const stepKeys = ['address', 'shipping', 'payment'] as const;
    trigger(stepKeys[currentStep]).then((isValid) => {
      if (isValid) {
        if (currentStep < totalSteps.length - 1) {
          setCurrentStep(currentStep + 1);
        } else {
          // Last step ΓåÆ place order
          placeOrder();
        }
      } else {
        toast.error('Please fill in all required fields');
      }
    });
  };

  // Place order
  const placeOrder = async () => {
    setIsSubmitting(true);
    try {
      // Simulate API call
      await new Promise((resolve) => setTimeout(resolve, 2000));
      const fakeOrderId = 'PJM' + Date.now().toString().slice(-8);
      setOrderId(fakeOrderId);
      setOrderComplete(true);
      clearCart();
      toast.success('Order placed successfully! ≡ƒÖÅ');
    } catch (error) {
      toast.error('Failed to place order. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  // Calculate order totals
  const shippingCost = watch('shipping.shippingMethod') === 'express' ? 499 : 0;
  const tax = Math.round(totalPrice * 0.18);
  const discount = 0; // placeholder for coupon logic
  const grandTotal = totalPrice + shippingCost + tax - discount;

  // If cart is empty, don't render
  if (items.length === 0) {
    return null;
  }

  // ============================================================
  // SUCCESS VIEW
  // ============================================================
  if (orderComplete) {
    return (
      <Container className="py-12 md:py-20">
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="max-w-2xl mx-auto bg-white rounded-2xl p-8 md:p-12 shadow-lg border border-gold/10 text-center"
        >
          <div className="w-24 h-24 mx-auto bg-green-100 rounded-full flex items-center justify-center mb-6">
            <Check className="w-12 h-12 text-green-600" />
          </div>
          <h1 className="font-cinzel text-3xl font-bold text-brown">Order Confirmed!</h1>
          <p className="text-brown-light mt-2">
            Thank you for your order. Your divine murti will be crafted with love and devotion.
          </p>
          <div className="bg-sand/30 rounded-xl p-4 my-6">
            <p className="text-sm text-brown-light">Order ID</p>
            <p className="font-cinzel text-xl font-bold text-gold-dark">{orderId}</p>
          </div>
          <p className="text-sm text-brown-light/70">
            We'll send you a confirmation email with tracking details shortly.
          </p>
          <div className="flex flex-wrap gap-4 justify-center mt-8">
            <Link href="/orders" className="btn-gold">
              View My Orders
            </Link>
            <Link href="/" className="btn-outline-gold">
              Continue Shopping
            </Link>
          </div>
        </motion.div>
      </Container>
    );
  }

  // ============================================================
  // CHECKOUT STEPS
  // ============================================================
  return (
    <Container className="py-8 md:py-12">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main content */}
        <div className="lg:col-span-2">
          {/* Step indicator */}
          <div className="flex items-center justify-between mb-8">
            {totalSteps.map((label, index) => (
              <div key={label} className="flex items-center flex-1">
                <button
                  onClick={() => goToStep(index)}
                  className={`flex items-center gap-2 ${
                    index <= currentStep ? 'text-brown' : 'text-brown-light/50'
                  }`}
                  disabled={index > currentStep}
                >
                  <div
                    className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium transition-all ${
                      index < currentStep
                        ? 'bg-gold text-white'
                        : index === currentStep
                        ? 'bg-gold text-white ring-4 ring-gold/20'
                        : 'bg-gray-200 text-gray-400'
                    }`}
                  >
                    {index < currentStep ? <Check className="w-4 h-4" /> : index + 1}
                  </div>
                  <span className="hidden sm:inline text-sm font-medium">
                    {label}
                  </span>
                </button>
                {index < totalSteps.length - 1 && (
                  <div
                    className={`flex-1 h-0.5 mx-2 ${
                      index < currentStep ? 'bg-gold' : 'bg-gray-200'
