                    <div>
                      <label className="block text-sm font-medium text-brown mb-1">
                        Full Name *
                      </label>
                      <Input
                        placeholder="Your full name"
                        {...register('address.fullName')}
                        className={errors.address?.fullName ? 'border-red-400' : ''}
