  },
  {
    id: 'PJM2025110',
    date: '2025-11-15T16:20:00Z',
    total: 5499,
    status: 'cancelled',
    items: [
      { name: 'Ram Darbar', quantity: 1, price: 5499, image: '/products/ramdarbar.jpg' },
    ],
    shippingAddress: '123, Murti Marg, Jaipur, Rajasthan 302001',
    paymentMethod: 'COD',
    trackingNumber: null,
  },
];

// ============================================================
// Orders Page
// ============================================================
export default function OrdersPage() {
  const router = useRouter();
  const { user } = useAuth();
  const [isLoading, setIsLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [expandedOrder, setExpandedOrder] = useState<string | null>(null);
  const [orders, setOrders] = useState(mockOrders);

  // Simulate loading
  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 600);
    return () => clearTimeout(timer);
  }, []);

  // Redirect if not logged in
  useEffect(() => {
    if (!user && !isLoading) {
      router.push('/login');
    }
  }, [user, isLoading, router]);

  // Filter orders
  const filteredOrders = orders.filter((order) => {
    const matchesSearch = order.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          order.items.some((item) => item.name.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesStatus = statusFilter === 'all' || order.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  // Format date
  const formatDate = (dateStr: string) => {
    return new Date(dateStr).toLocaleDateString('en-IN', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  // Status badge component
  const StatusBadge = ({ status }: { status: string }) => {
    const statusMap: Record<string, { label: string; icon: any; className: string }> = {
      pending: { label: 'Pending', icon: Clock, className: 'bg-yellow-100 text-yellow-700' },
      shipped: { label: 'Shipped', icon: Truck, className: 'bg-blue-100 text-blue-700' },
      delivered: { label: 'Delivered', icon: CheckCircle, className: 'bg-green-100 text-green-700' },
      cancelled: { label: 'Cancelled', icon: XCircle, className: 'bg-red-100 text-red-700' },
    };
    const info = statusMap[status] || statusMap.pending;
    const Icon = info.icon;
    return (
      <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium ${info.className}`}>
        <Icon className="w-3.5 h-3.5" />
        {info.label}
      </span>
    );
  };

  // Toggle order details
  const toggleOrderDetails = (orderId: string) => {
    setExpandedOrder(expandedOrder === orderId ? null : orderId);
  };

  // Track order action
  const handleTrackOrder = (orderId: string) => {
    toast.success(`Tracking order ${orderId}`);
    // Navigate to tracking page
    // router.push(`/track-order/${orderId}`);
  };

  // Download invoice
  const handleDownloadInvoice = (orderId: string) => {
    toast.success(`Downloading invoice for ${orderId}`);
    // Trigger download
  };

  // Cancel order
  const handleCancelOrder = (orderId: string) => {
    toast.success(`Order ${orderId} cancelled`);
    // Update status
    setOrders((prev) =>
      prev.map((o) =>
        o.id === orderId ? { ...o, status: 'cancelled' } : o
      )
    );
  };

  // Loading state
  if (isLoading) {
    return <OrdersSkeleton />;
  }

  // If no user, return null (will redirect)
  if (!user) return null;

  // Get unique statuses for filter
  const statuses = ['all', ...new Set(orders.map((o) => o.status))];

  return (
    <Container className="py-8 md:py-12">
      {/* Page header */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div>
            <h1 className="font-cinzel text-2xl md:text-3xl font-bold text-brown">My Orders</h1>
            <p className="text-brown-light text-sm mt-1">
              Track and manage all your orders in one place.
            </p>
          </div>
          <div className="flex items-center gap-3">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-brown-light" />
              <Input
                type="text"
                placeholder="Search by order ID or product..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 pr-4 py-2 text-sm border-gold/10 rounded-full w-full md:w-64"
              />
            </div>
            <div className="relative">
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="appearance-none pl-4 pr-10 py-2 text-sm border border-gold/10 rounded-full bg-white focus:outline-none focus:ring-2 focus:ring-gold/20"
              >
                {statuses.map((status) => (
                  <option key={status} value={status}>
                    {status === 'all' ? 'All Status' : status.charAt(0).toUpperCase() + status.slice(1)}
                  </option>
                ))}
              </select>
              <Filter className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-brown-light pointer-events-none" />
            </div>
          </div>
        </div>
      </motion.div>

      {/* Order count */}
      <p className="text-sm text-brown-light/70 mb-4">
        {filteredOrders.length} {filteredOrders.length === 1 ? 'order' : 'orders'} found
      </p>

      {/* Orders list */}
      {filteredOrders.length === 0 ? (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="text-center py-16 bg-white rounded-2xl border border-gold/5"
        >
          <Package className="w-16 h-16 text-brown-light/20 mx-auto mb-4" />
          <h3 className="font-cinzel text-xl text-brown">No orders found</h3>
          <p className="text-brown-light text-sm mt-2">
            {searchTerm || statusFilter !== 'all'
              ? 'Try adjusting your search or filters.'
              : 'You haven\'t placed any orders yet.'}
          </p>
          <Link href="/products" className="btn-gold inline-block mt-6">
            Browse Collection
          </Link>
        </motion.div>
      ) : (
        <div className="space-y-4">
          {filteredOrders.map((order, index) => (
            <motion.div
              key={order.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3, delay: index * 0.05 }}
              className="bg-white rounded-2xl border border-gold/5 shadow-sm hover:shadow-md transition-shadow overflow-hidden"
            >
              {/* Order summary (always visible) */}
              <div
                className="p-4 md:p-6 cursor-pointer"
                onClick={() => toggleOrderDetails(order.id)}
              >
                <div className="flex flex-wrap items-start justify-between gap-3">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-3">
                      <span className="font-cinzel text-sm font-semibold text-brown">
                        {order.id}
                      </span>
                      <StatusBadge status={order.status} />
                    </div>
                    <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-1 text-sm text-brown-light">
                      <span>{formatDate(order.date)}</span>
                      <span>ΓÇó</span>
                      <span>{order.items.length} {order.items.length === 1 ? 'item' : 'items'}</span>
                      <span>ΓÇó</span>
                      <span>{order.paymentMethod}</span>
                    </div>
                  </div>
                  <div className="flex items-center gap-4">
                    <span className="font-cinzel text-lg text-gold-dark">
                      Γé╣{formatPrice(order.total)}
                    </span>
                    <button
                      className="p-2 rounded-full hover:bg-gold/10 transition-colors"
                      aria-label={expandedOrder === order.id ? 'Collapse' : 'Expand'}
                    >
                      {expandedOrder === order.id ? (
                        <ChevronUp className="w-5 h-5 text-brown-light" />
                      ) : (
                        <ChevronDown className="w-5 h-5 text-brown-light" />
                      )}
                    </button>
                  </div>
                </div>
              </div>

              {/* Expanded details */}
              <AnimatePresence>
                {expandedOrder === order.id && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{ duration: 0.3 }}
                    className="border-t border-gold/10 px-4 md:px-6 py-4"
                  >
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {/* Items */}
                      <div>
                        <h4 className="font-medium text-sm text-brown mb-2">Items</h4>
                        <div className="space-y-2">
                          {order.items.map((item, idx) => (
                            <div key={idx} className="flex items-center justify-between text-sm">
                              <div className="flex items-center gap-2">
                                <span>{item.quantity} ├ù</span>
                                <span className="text-brown">{item.name}</span>
                              </div>
                              <span className="font-cinzel text-gold-dark">Γé╣{formatPrice(item.price * item.quantity)}</span>
                            </div>
                          ))}
                        </div>
                        <div className="mt-3 pt-2 border-t border-gold/10 flex justify-between text-sm font-medium">
                          <span>Total</span>
                          <span className="font-cinzel text-gold-dark">Γé╣{formatPrice(order.total)}</span>
                        </div>
                      </div>

                      {/* Details */}
                      <div>
                        <h4 className="font-medium text-sm text-brown mb-2">Order Details</h4>
                        <div className="space-y-2 text-sm text-brown-light">
                          <p><span className="font-medium text-brown">Payment:</span> {order.paymentMethod}</p>
                          <p><span className="font-medium text-brown">Shipping:</span> {order.shippingAddress}</p>
                          {order.trackingNumber && (
                            <p><span className="font-medium text-brown">Tracking:</span> {order.trackingNumber}</p>
                          )}
                          <p><span className="font-medium text-brown">Placed on:</span> {formatDate(order.date)}</p>
                        </div>

                        {/* Actions */}
                        <div className="flex flex-wrap gap-2 mt-4">
                          {order.status === 'shipped' && order.trackingNumber && (
                            <button
                              onClick={() => handleTrackOrder(order.id)}
                              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors"
                            >
                              <Truck className="w-4 h-4" />
                              Track
                            </button>
                          )}
                          <button
                            onClick={() => handleDownloadInvoice(order.id)}
                            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm bg-gold/10 text-gold-dark rounded-lg hover:bg-gold/20 transition-colors"
                          >
                            <Download className="w-4 h-4" />
                            Invoice
                          </button>
                          {order.status === 'pending' && (
                            <button
                              onClick={() => handleCancelOrder(order.id)}
                              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm bg-red-50 text-red-500 rounded-lg hover:bg-red-100 transition-colors"
                            >
                              <XCircle className="w-4 h-4" />
                              Cancel
                            </button>
                          )}
                          <Link
                            href={`/orders/${order.id}`}
                            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-sm border border-gold/20 text-brown rounded-lg hover:bg-gold/5 transition-colors"
                          >
                            <Eye className="w-4 h-4" />
                            View Full Details
                          </Link>
                        </div>
                      </div>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          ))}
        </div>
      )}

      {/* Back to profile link */}
      <div className="mt-8 text-center">
        <Link href="/profile" className="text-sm text-brown-light hover:text-gold-dark transition-colors inline-flex items-center gap-1">
          <ChevronRight className="w-4 h-4 rotate-180" />
          Back to Profile
        </Link>
      </div>
    </Container>
  );
}

// ============================================================
// SKELETON LOADER
// ============================================================
function OrdersSkeleton() {
  return (
    <Container className="py-8 md:py-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <Skeleton className="h-8 w-48" />
          <Skeleton className="h-4 w-64 mt-1" />
        </div>
        <div className="flex gap-3">
          <Skeleton className="h-10 w-64 rounded-full" />
          <Skeleton className="h-10 w-32 rounded-full" />
        </div>
      </div>
      <div className="space-y-4">
        {Array.from({ length: 3 }).map((_, i) => (
          <div key={i} className="bg-white rounded-2xl border border-gold/5 p-6">
            <div className="flex items-start justify-between">
              <div className="flex-1 space-y-2">
                <Skeleton className="h-5 w-32" />
                <Skeleton className="h-4 w-48" />
              </div>
              <div className="flex items-center gap-4">
                <Skeleton className="h-6 w-20" />
                <Skeleton className="h-8 w-8 rounded-full" />
              </div>
            </div>
          </div>
        ))}
      </div>
    </Container>
  );
}

// frontend/src/app/page.tsx

'use client';

import { useEffect } from 'react';
import Lenis from 'lenis';
import gsap from 'gsap';
import ScrollTrigger from 'gsap/ScrollTrigger';

// Sections
import Hero from '../components/hero/Hero';
import FeaturedCategories from '../components/sections/FeaturedCategories';
import FeaturedProducts from '../components/sections/FeaturedProducts';
import Testimonials from '../components/sections/Testimonials';
import Newsletter from '../components/sections/Newsletter';
import FAQAccordion from '../components/sections/FAQAccordion';
import StatsSection from '../components/sections/StatsSection';
import WorkshopSection from '../components/sections/WorkshopSection';
import InstagramFeed from '../components/sections/InstagramFeed';
import VideoSection from '../components/sections/VideoSection';

// Animation wrapper
import { ScrollReveal } from '../components/animations/ScrollReveal';

// Custom hook for homepage data
import { useHomeData } from '../features/home/hooks/useHomeData';
import type {
  FeaturedProduct as HomeFeaturedProduct,
  HomeStats,
  InstagramPost as HomeInstagramPost,
  YouTubeVideo as HomeYouTubeVideo,
} from '../features/home/types/home.types';

// Loading skeleton
import HomePageSkeleton from '../components/loaders/HomePageSkeleton';

// Types expected by section components (lighter home-page data shapes
// don't carry every field of the full domain types, so we adapt them
// here rather than changing the already-fixed component prop types)
import type { Product } from '../features/products/types/product.types';
import type { StatItem } from '../components/sections/StatsSection';

// Register GSAP plugins
if (typeof window !== 'undefined') {
  gsap.registerPlugin(ScrollTrigger);
}

export default function HomePage() {
  const { data, isLoading, error } = useHomeData();

  // Initialize Lenis smooth scroll
  useEffect(() => {
    const lenis = new Lenis({
      duration: 1.2,
      easing: (t: number) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
      orientation: 'vertical',
      smoothWheel: true,
    });

    // Connect GSAP ScrollTrigger to Lenis
    lenis.on('scroll', ScrollTrigger.update);
    gsap.ticker.add((time: number) => lenis.raf(time * 1000));
    gsap.ticker.lagSmoothing(0);

    return () => {
      lenis.destroy();
      gsap.ticker.remove(lenis.raf);
    };
  }, []);

  // Loading state
  if (isLoading) {
    return <HomePageSkeleton />;
  }

  // Error state
  if (error) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center">
        <p className="text-maroon text-xl">Failed to load homepage</p>
        <button
          onClick={() => window.location.reload()}
          className="mt-4 btn-gold"
        >
          Retry
        </button>
      </div>
    );
  }

  // Destructure data from API
  const {
    categories = [],
    featuredProducts = [],
    trendingProducts = [],
    testimonials = [],
    faqs = [],
    stats,
    instagramPosts = [],
    youtubeVideos = [],
  } = data || {};

  // Adapt lightweight home-page product/stat shapes to the richer types
  // expected by the shared section components, without altering any
  // visual output (all fields read by those components are present here).
  const toDisplayProduct = (p: HomeFeaturedProduct): Product => ({
    ...p,
    description: '',
    category: '',
    inStock: true,
    createdAt: '',
    updatedAt: '',
  });
  const displayFeaturedProducts: Product[] = featuredProducts.map(toDisplayProduct);
  const displayTrendingProducts: Product[] = trendingProducts.map(toDisplayProduct);
  const displayStats: StatItem[] = stats
    ? [
        { id: 'customers', icon: '≡ƒÖÅ', value: stats.totalCustomers ?? 0, label: 'Happy Devotees' },
        { id: 'products', icon: '≡ƒ¬╖', value: stats.totalProducts ?? 0, label: 'Murtis Created' },
        { id: 'orders', icon: '≡ƒôª', value: stats.totalOrders ?? 0, label: 'Orders Delivered' },
        { id: 'years', icon: '≡ƒÅ¢∩╕Å', value: stats.yearsOfExperience ?? 0, label: 'Years of Craftsmanship' },
      ]
    : [];
  const displayInstagramPosts = instagramPosts.map((post) => ({
    id: post.id,
    image: post.imageUrl,
    caption: post.caption,
    likes: post.likes,
    url: post.link || '#',
  }));
  const displayYoutubeVideos = youtubeVideos.map((video) => ({
    id: video.id,
    title: video.title,
    thumbnail: video.thumbnailUrl || '',
    videoUrl: video.url || '',
  }));

  return (
    <>
      {/* 1. Hero Section ΓÇô no scroll reveal (full viewport) */}
      <Hero />

      {/* 2. Featured Categories */}
      <ScrollReveal>
        <FeaturedCategories categories={categories} />
      </ScrollReveal>

      {/* 3. Featured Products */}
      <ScrollReveal>
        <FeaturedProducts
          title="Popular Murtis"
          subtitle="Timeless sculptures that bring peace, prosperity, and devotion."
          products={displayFeaturedProducts}
        />
      </ScrollReveal>

      {/* 4. Stats Section */}
      <ScrollReveal>
        <StatsSection stats={displayStats} />
      </ScrollReveal>

      {/* 5. Workshop / Behind the Art */}
      <ScrollReveal>
        <WorkshopSection />
      </ScrollReveal>

      {/* 6. Trending Products (slider) */}
      <ScrollReveal>
        <FeaturedProducts
          title="Trending Now"
          subtitle="Most loved by our devotees this season."
          products={displayTrendingProducts}
          isSlider={true}
        />
      </ScrollReveal>

      {/* 7. Testimonials */}
      <ScrollReveal>
        <Testimonials testimonials={testimonials} />
      </ScrollReveal>

      {/* 8. Instagram Feed */}
      <ScrollReveal>
        <InstagramFeed posts={displayInstagramPosts} />
      </ScrollReveal>

      {/* 9. YouTube / Video Section */}
      <ScrollReveal>
        <VideoSection videos={displayYoutubeVideos} />
      </ScrollReveal>

      {/* 10. FAQ Accordion */}
      <ScrollReveal>
        <FAQAccordion faqs={faqs} />
      </ScrollReveal>

      {/* 11. Newsletter */}
      <ScrollReveal>
        <Newsletter />
      </ScrollReveal>
    </>
  );
}

