// frontend/src/components/animations/ParallaxImage.tsx

'use client';

import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import Image from 'next/image';
import { useMotionValue, useSpring, useTransform, motion } from 'framer-motion';
import { cn } from '../../lib/utils';

// ============================================================
// Types
// ============================================================
export interface ParallaxImageProps {
  /**
   * Image source URL
   */
  src: string;
  /**
   * Image alt text
   */
  alt: string;
  /**
   * Additional image className
   */
  imageClassName?: string;
  /**
   * Container className
   */
  className?: string;
  /**
   * Aspect ratio of the container
   * @default '16/9'
   */
  aspectRatio?: '1/1' | '4/3' | '16/9' | '21/9' | '3/2' | string;
  /**
   * The intensity of the parallax effect (0-1)
   * @default 0.3
   */
  intensity?: number;
  /**
   * The type of parallax effect
   * @default 'both'
   */
  type?: 'mouse' | 'scroll' | 'both';
  /**
   * Direction of the parallax effect
   * @default 'both'
   */
  direction?: 'horizontal' | 'vertical' | 'both';
  /**
   * Whether to reverse the parallax direction
   * @default false
   */
  reverse?: boolean;
  /**
   * Whether to enable the effect on mobile
   * @default true
   */
  enableOnMobile?: boolean;
  /**
   * Whether to enable the effect on touch devices
   * @default true
   */
  enableOnTouch?: boolean;
  /**
   * Whether to use a circular reveal mask
   * @default false
   */
  circular?: boolean;
  /**
   * Whether to show a loading skeleton
   * @default false
   */
  loading?: boolean;
  /**
   * Whether the image should be priority loaded
   * @default false
   */
  priority?: boolean;
  /**
   * Overlay gradient on the image
   */
  overlay?: React.ReactNode;
  /**
   * The damping for the spring animation
   * @default 20
   */
  damping?: number;
  /**
   * The stiffness for the spring animation
   * @default 150
   */
  stiffness?: number;
  /**
   * Children to render over the image
   */
  children?: React.ReactNode;
  /**
   * Whether to apply a glass effect overlay
   * @default false
   */
  glassEffect?: boolean;
}

// ============================================================
// useParallax ΓÇô Custom hook for parallax logic
// ============================================================
function useParallax({
  intensity = 0.3,
  type = 'both',
  direction = 'both',
  reverse = false,
  enableOnMobile = true,
  enableOnTouch = true,
  damping = 20,
  stiffness = 150,
}: {
  intensity?: number;
  type?: 'mouse' | 'scroll' | 'both';
  direction?: 'horizontal' | 'vertical' | 'both';
  reverse?: boolean;
  enableOnMobile?: boolean;
  enableOnTouch?: boolean;
  damping?: number;
  stiffness?: number;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isMounted, setIsMounted] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const [isTouch, setIsTouch] = useState(false);

  // Motion values
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);
  const scrollY = useMotionValue(0);

  // Spring animations
  const springX = useSpring(mouseX, { damping, stiffness });
  const springY = useSpring(mouseY, { damping, stiffness });
  const springScroll = useSpring(scrollY, { damping: 30, stiffness: 100 });

  // Transform values
  const maxOffset = useMemo(() => 40 * intensity, [intensity]);
  const maxScrollOffset = useMemo(() => 60 * intensity, [intensity]);

  const transformX = useTransform(springX, [-1, 1], reverse ? [maxOffset, -maxOffset] : [-maxOffset, maxOffset]);
  const transformY = useTransform(springY, [-1, 1], reverse ? [maxOffset, -maxOffset] : [-maxOffset, maxOffset]);
  const transformScroll = useTransform(
    springScroll,
    [-0.5, 0.5],
    reverse ? [maxScrollOffset, -maxScrollOffset] : [-maxScrollOffset, maxScrollOffset]
  );

  // Check device capabilities (must run after mount since it reads browser-only
  // APIs; this is a one-time hydration-safe detection, not derivable at render time)
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- one-time browser capability detection on mount, cannot be derived during render without risking SSR/client mismatch
    setIsMounted(true);
    const isMobileDevice = window.innerWidth < 768;
    const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
    setIsMobile(isMobileDevice);
    setIsTouch(isTouchDevice);
  }, []);

  // Handle mouse movement
  const handleMouseMove = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      if (!containerRef.current) return;
      if (isMobile && !enableOnMobile) return;
      if (isTouch && !enableOnTouch) return;

      const rect = containerRef.current.getBoundingClientRect();
      const x = (e.clientX - rect.left) / rect.width;
      const y = (e.clientY - rect.top) / rect.height;

      const normalizedX = (x * 2) - 1;
      const normalizedY = (y * 2) - 1;

      if (type === 'mouse' || type === 'both') {
        if (direction === 'horizontal' || direction === 'both') {
          mouseX.set(normalizedX);
        }
        if (direction === 'vertical' || direction === 'both') {
          mouseY.set(normalizedY);
        }
      }
    },
    [
      containerRef,
      isMobile,
      isTouch,
      enableOnMobile,
      enableOnTouch,
      type,
      direction,
      mouseX,
      mouseY,
    ]
  );

  // Handle mouse leave
  const handleMouseLeave = useCallback(() => {
    mouseX.set(0);
    mouseY.set(0);
  }, [mouseX, mouseY]);

  // Handle scroll
  useEffect(() => {
    if (type !== 'scroll' && type !== 'both') return;

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const viewportHeight = window.innerHeight;

      // Calculate how much of the element is visible (-1 to 1)
      const visibleRatio = 1 - (rect.top / viewportHeight);
      const clampedRatio = Math.min(Math.max(visibleRatio * 2 - 1, -1), 1);

      scrollY.set(clampedRatio);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();

    return () => window.removeEventListener('scroll', handleScroll);
  }, [type, scrollY]);

  // Determine which transform to use
  const getTransform = useCallback(() => {
    const transforms: string[] = [];

    if (type === 'mouse' || type === 'both') {
      if (direction === 'horizontal' || direction === 'both') {
        transforms.push(`translateX(${transformX.get()}px)`);
      }
      if (direction === 'vertical' || direction === 'both') {
        transforms.push(`translateY(${transformY.get()}px)`);
      }
    }

    if (type === 'scroll' || type === 'both') {
      if (direction === 'vertical' || direction === 'both') {
        transforms.push(`translateY(${transformScroll.get()}px)`);
      }
      if (direction === 'horizontal' || direction === 'both') {
        transforms.push(`translateX(${transformScroll.get() * 0.5}px)`);
      }
    }

    return transforms.join(' ') || 'none';
  }, [transformX, transformY, transformScroll, type, direction]);

  return {
    containerRef,
    handleMouseMove,
    handleMouseLeave,
    getTransform,
    transformX,
    transformY,
    transformScroll,
    isMounted,
    isMobile,
    isTouch,
  };
}

// ============================================================
// ParallaxImage Component
// ============================================================
export function ParallaxImage({
  src,
  alt,
  imageClassName,
  className,
  aspectRatio = '16/9',
  intensity = 0.3,
  type = 'both',
  direction = 'both',
  reverse = false,
  enableOnMobile = true,
  enableOnTouch = true,
  circular = false,
  loading = false,
  priority = false,
  overlay,
  damping = 20,
  stiffness = 150,
  children,
  glassEffect = false,
  ...props
}: ParallaxImageProps) {
  const {
    containerRef,
    handleMouseMove,
    handleMouseLeave,
    transformX,
    transformY,
    transformScroll,
    isMounted,
    isMobile,
    isTouch,
  } = useParallax({
    intensity,
    type,
    direction,
    reverse,
    enableOnMobile,
    enableOnTouch,
    damping,
    stiffness,
  });

  const [isImageLoaded, setIsImageLoaded] = useState(false);

  // Determine if parallax should be active
  const shouldParallax = useMemo(() => {
    if (loading) return false;
    if (isMobile && !enableOnMobile) return false;
    if (isTouch && !enableOnTouch) return false;
    return true;
  }, [loading, isMobile, enableOnMobile, isTouch, enableOnTouch]);

  // Aspect ratio class
  const aspectRatioClasses = {
    '1/1': 'aspect-square',
    '4/3': 'aspect-[4/3]',
    '16/9': 'aspect-[16/9]',
    '21/9': 'aspect-[21/9]',
    '3/2': 'aspect-[3/2]',
  };

  const aspectClass = aspectRatio in aspectRatioClasses
    ? aspectRatioClasses[aspectRatio as keyof typeof aspectRatioClasses]
    : `aspect-[${aspectRatio}]`;

  // Loading skeleton
  if (loading) {
    return (
      <div
        className={cn(
          'relative overflow-hidden bg-sand/50 dark:bg-brown/50 animate-pulse',
          aspectClass,
          circular && 'rounded-full',
          className
        )}
      />
    );
  }

  return (
    <div
      ref={containerRef}
      className={cn(
        'relative overflow-hidden',
        aspectClass,
        circular && 'rounded-full',
        glassEffect && 'after:absolute after:inset-0 after:bg-white/10 after:backdrop-blur-[2px] after:pointer-events-none',
        className
      )}
      onMouseMove={shouldParallax ? handleMouseMove : undefined}
      onMouseLeave={shouldParallax ? handleMouseLeave : undefined}
      {...props}
    >
      {/* Image with parallax transform */}
      <motion.div
        className={cn(
          'absolute inset-0 w-full h-full',
          !isImageLoaded && 'opacity-0'
        )}
        style={{
          transform: shouldParallax
            ? `translate(${transformX.get() * 0.3}px, ${transformY.get() * 0.3}px)`
            : 'none',
        }}
        animate={{
          scale: shouldParallax ? 1.05 : 1,
        }}
        transition={{
          type: 'spring',
          damping: 30,
          stiffness: 200,
        }}
      >
        <Image
          src={src}
          alt={alt}
          fill
          className={cn(
            'object-cover transition-opacity duration-500',
            imageClassName
          )}
          priority={priority}
          onLoad={() => setIsImageLoaded(true)}
          sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
        />

        {/* Inner parallax layer (for double parallax effect) */}
        {shouldParallax && (
          <motion.div
            className="absolute inset-0 w-full h-full"
            style={{
              transform: `translate(${transformX.get() * -0.15}px, ${transformY.get() * -0.15}px)`,
            }}
          />
        )}
      </motion.div>

      {/* Overlay gradient */}
      {overlay && (
        <div className="absolute inset-0 pointer-events-none z-10">
          {overlay}
        </div>
      )}

      {/* Children content */}
      {children && (
        <div className="absolute inset-0 z-20 flex items-center justify-center">
          {children}
        </div>
      )}

      {/* Loading skeleton placeholder */}
      {!isImageLoaded && !loading && (
        <div className="absolute inset-0 flex items-center justify-center bg-sand/30 dark:bg-brown/30">
          <div className="w-8 h-8 border-2 border-gold border-t-transparent rounded-full animate-spin" />
        </div>
      )}
    </div>
  );
}

// ============================================================
// ParallaxContainer ΓÇô For grouping multiple parallax elements
// ============================================================
export interface ParallaxContainerProps {
  children: React.ReactNode;
  className?: string;
  /**
   * The intensity of the parallax effect for all children
   * @default 0.2
   */
  intensity?: number;
  /**
   * The type of parallax effect
   * @default 'mouse'
   */
  type?: 'mouse' | 'scroll' | 'both';
  /**
   * Whether to apply a subtle perspective transform to the container
   * @default true
   */
  perspective?: boolean;
  /**
   * The perspective value in pixels
   * @default 1000
   */
  perspectiveValue?: number;
}

export function ParallaxContainer({
  children,
  className,
  intensity = 0.2,
  type = 'mouse',
  perspective = true,
  perspectiveValue = 1000,
}: ParallaxContainerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [mouseX, setMouseX] = useState(0);
  const [mouseY, setMouseY] = useState(0);

  const handleMouseMove = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;
    setMouseX((x * 2) - 1);
    setMouseY((y * 2) - 1);
  }, []);

  const handleMouseLeave = useCallback(() => {
    setMouseX(0);
    setMouseY(0);
  }, []);

  const rotateX = useSpring(useMotionValue(mouseY * intensity * 5), { damping: 20, stiffness: 150 });
  const rotateY = useSpring(useMotionValue(mouseX * intensity * 5), { damping: 20, stiffness: 150 });

  return (
    <motion.div
      ref={containerRef}
      className={cn('relative', className)}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{
        perspective: perspective ? perspectiveValue : undefined,
        transformStyle: 'preserve-3d',
        rotateX: perspective && type !== 'scroll' ? rotateX : 0,
        rotateY: perspective && type !== 'scroll' ? rotateY : 0,
      }}
      transition={{
        type: 'spring',
        damping: 25,
        stiffness: 200,
      }}
    >
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child as React.ReactElement<Record<string, unknown>>, {
            intensity: intensity * 0.5,
            type: type,
          });
        }
        return child;
      })}
    </motion.div>
  );
}

// ============================================================
// ParallaxImageSkeleton ΓÇô Loading placeholder
// ============================================================
export function ParallaxImageSkeleton({
  className,
  aspectRatio = '16/9',
  circular = false,
  count = 1,
}: {
  className?: string;
  aspectRatio?: '1/1' | '4/3' | '16/9' | '21/9' | '3/2' | string;
  circular?: boolean;
  count?: number;
}) {
  const aspectRatioClasses = {
    '1/1': 'aspect-square',
    '4/3': 'aspect-[4/3]',
    '16/9': 'aspect-[16/9]',
    '21/9': 'aspect-[21/9]',
    '3/2': 'aspect-[3/2]',
  };

  const aspectClass = aspectRatio in aspectRatioClasses
    ? aspectRatioClasses[aspectRatio as keyof typeof aspectRatioClasses]
    : `aspect-[${aspectRatio}]`;

  if (count > 1) {
    return (
      <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
        {Array.from({ length: count }).map((_, i) => (
          <div
            key={i}
            className={cn(
              'bg-sand/50 dark:bg-brown/50 animate-pulse',
              aspectClass,
              circular && 'rounded-full',
              className
            )}
          />
        ))}
      </div>
    );
  }

  return (
    <div
      className={cn(
        'bg-sand/50 dark:bg-brown/50 animate-pulse',
        aspectClass,
        circular && 'rounded-full',
        className
      )}
    />
  );
}

// ============================================================
// ParallaxImageGallery ΓÇô Gallery with parallax images
// ============================================================
export interface ParallaxImageGalleryProps {
  images: Array<{
    src: string;
    alt: string;
    caption?: string;
  }>;
  className?: string;
  intensity?: number;
  type?: 'mouse' | 'scroll' | 'both';
  columns?: 2 | 3 | 4;
  gap?: 'sm' | 'default' | 'lg';
  aspectRatio?: '1/1' | '4/3' | '16/9' | '3/2';
}

export function ParallaxImageGallery({
  images,
  className,
  intensity = 0.2,
  type = 'mouse',
  columns = 3,
  gap = 'default',
  aspectRatio = '16/9',
}: ParallaxImageGalleryProps) {
  const columnClasses = {
    2: 'grid-cols-1 sm:grid-cols-2',
    3: 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3',
    4: 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-4',
  };

  const gapClasses = {
    sm: 'gap-3',
    default: 'gap-4 md:gap-6',
    lg: 'gap-6 md:gap-8',
  };

  return (
    <div className={cn('grid', columnClasses[columns], gapClasses[gap], className)}>
      {images.map((image, index) => (
        <ParallaxImage
          key={index}
          src={image.src}
          alt={image.alt}
          aspectRatio={aspectRatio}
          intensity={intensity}
          type={type}
          className="group"
        >
          {image.caption && (
            <div className="absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-black/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300">
              <p className="text-white text-sm font-medium text-center">{image.caption}</p>
            </div>
          )}
        </ParallaxImage>
      ))}
    </div>
  );
}

// ============================================================
// Default export
// ============================================================
export default ParallaxImage;

// frontend/src/components/animations/ScrollReveal.tsx

'use client';

import React, { useRef, useState, useCallback, useMemo } from 'react';
import { motion, useInView, useReducedMotion, Variants, HTMLMotionProps, Transition } from 'framer-motion';
import { cn } from '../../lib/utils';

// ============================================================
// Types
// ============================================================
export type RevealVariant =
  | 'fadeUp'
  | 'fadeDown'
  | 'fadeLeft'
  | 'fadeRight'
  | 'fadeScale'
  | 'fade'
  | 'scale'
  | 'stagger'
  | 'slideUp'
  | 'slideDown'
  | 'slideLeft'
  | 'slideRight'
  | 'zoomIn'
  | 'zoomOut'
  | 'flip'
  | 'blur';

export interface ScrollRevealProps extends Omit<HTMLMotionProps<'div'>, 'variants'> {
  /**
   * The animation variant to apply
   * @default 'fadeUp'
   */
  variant?: RevealVariant;
  /**
   * Custom variants object (overrides variant prop)
   */
  customVariants?: Variants;
  /**
   * Animation duration in seconds
   * @default 0.6
   */
  duration?: number;
  /**
   * Animation delay in seconds
   * @default 0
   */
  delay?: number;
  /**
   * Stagger children delay in seconds (for stagger variants)
   * @default 0.05
   */
  staggerChildren?: number;
  /**
   * Amount of element that must be visible before triggering (0-1)
   * @default 0.2
   */
  threshold?: number;
  /**
   * Whether to trigger once or every time element comes into view
   * @default true
   */
  once?: boolean;
  /**
   * Custom className for the wrapper
   */
  className?: string;
  /**
   * Children elements
   */
  children: React.ReactNode;
  /**
   * Whether to animate on initial mount
   * @default true
   */
  animateOnMount?: boolean;
  /**
   * Whether to disable animations (for performance or preference)
   * @default false
   */
  disabled?: boolean;
  /**
   * Root margin for IntersectionObserver
   * @default '0px 0px -50px 0px'
   */
  rootMargin?: string;
  /**
   * Whether to apply a subtle scale effect
   * @default false
   */
  subtle?: boolean;
  /**
   * Whether to use a snap effect (element snaps into place)
   * @default false
   */
  snap?: boolean;
}

// ============================================================
// Default variants
// ============================================================
export const revealVariants: Record<RevealVariant, Variants> = {
  fadeUp: {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0 },
  },
  fadeDown: {
    hidden: { opacity: 0, y: -40 },
    visible: { opacity: 1, y: 0 },
  },
  fadeLeft: {
    hidden: { opacity: 0, x: -40 },
    visible: { opacity: 1, x: 0 },
  },
  fadeRight: {
    hidden: { opacity: 0, x: 40 },
    visible: { opacity: 1, x: 0 },
  },
  fadeScale: {
    hidden: { opacity: 0, scale: 0.9 },
    visible: { opacity: 1, scale: 1 },
  },
  fade: {
    hidden: { opacity: 0 },
    visible: { opacity: 1 },
  },
  scale: {
    hidden: { scale: 0.8 },
    visible: { scale: 1 },
  },
  stagger: {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        staggerChildren: 0.1,
      },
    },
  },
  slideUp: {
    hidden: { y: 60, opacity: 0 },
    visible: { y: 0, opacity: 1 },
  },
  slideDown: {
    hidden: { y: -60, opacity: 0 },
    visible: { y: 0, opacity: 1 },
  },
  slideLeft: {
    hidden: { x: -60, opacity: 0 },
    visible: { x: 0, opacity: 1 },
  },
  slideRight: {
    hidden: { x: 60, opacity: 0 },
    visible: { x: 0, opacity: 1 },
  },
  zoomIn: {
    hidden: { scale: 0.6, opacity: 0 },
    visible: { scale: 1, opacity: 1 },
  },
  zoomOut: {
    hidden: { scale: 1.4, opacity: 0 },
    visible: { scale: 1, opacity: 1 },
  },
  flip: {
    hidden: { rotateX: 90, opacity: 0 },
    visible: { rotateX: 0, opacity: 1 },
  },
  blur: {
    hidden: { filter: 'blur(12px)', opacity: 0 },
    visible: { filter: 'blur(0px)', opacity: 1 },
  },
};

// ============================================================
// Child stagger variants
// ============================================================
export const staggerItemVariants: Variants = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.5,
      ease: 'easeOut',
    },
  },
};

// ============================================================
// ScrollReveal Component
// ============================================================
export function ScrollReveal({
  variant = 'fadeUp',
  customVariants,
  duration = 0.6,
  delay = 0,
  staggerChildren = 0.05,
  threshold = 0.2,
  once = true,
  className,
  children,
  animateOnMount = true,
  disabled = false,
  rootMargin = '0px 0px -50px 0px',
  subtle = false,
  snap = false,
  ...props
}: ScrollRevealProps) {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, {
    amount: threshold,
    once,
    margin: rootMargin as NonNullable<Parameters<typeof useInView>[1]>['margin'],
  });
  const prefersReducedMotion = useReducedMotion();
  const [hasAnimated, setHasAnimated] = useState(false);

  // Determine if animation should be active
  const shouldAnimate = useMemo(() => {
    if (disabled) return false;
    if (prefersReducedMotion) return false;
    if (!animateOnMount && !isInView) return false;
    return true;
  }, [disabled, prefersReducedMotion, animateOnMount, isInView]);

  // Track animation state (derived during render instead of in an effect,
  // to avoid the extra render pass caused by setState-in-effect)
  const [prevIsInView, setPrevIsInView] = useState(isInView);
  if (isInView !== prevIsInView) {
    setPrevIsInView(isInView);
    if (isInView && once && !hasAnimated) {
      setHasAnimated(true);
    }
  }

  // Get the appropriate variants
  const getVariants = useCallback((): Variants => {
    if (customVariants) return customVariants;
    if (variant === 'stagger') {
      return {
        hidden: { opacity: 0, y: 20 },
        visible: {
          opacity: 1,
          y: 0,
          transition: {
            staggerChildren,
            delayChildren: delay,
            duration,
            ease: 'easeOut',
          },
        },
      };
    }
    return revealVariants[variant] || revealVariants.fadeUp;
  }, [customVariants, variant, staggerChildren, delay, duration]);

  // Get transition config
  const getTransition = useCallback((): Transition => {
    if (variant === 'stagger') {
      return {
        staggerChildren,
        delayChildren: delay,
      };
    }
    if (snap) {
      return {
        duration,
        delay,
        ease: [0.34, 1.56, 0.64, 1],
        type: 'spring',
        damping: 20,
        stiffness: 200,
      };
    }
    return {
      duration,
      delay,
      ease: 'easeOut',
      type: 'tween',
    };
  }, [variant, staggerChildren, delay, duration, snap]);

  // Compute final variants
  const variants = getVariants();
  const transition = getTransition();

  // If disabled or prefers reduced motion, render children without animation
  if (disabled || prefersReducedMotion) {
    return (
      <div ref={ref} className={className}>
        {children}
      </div>
    );
  }

  // If it's a stagger variant, wrap children in motion.div with stagger
  if (variant === 'stagger') {
    return (
      <motion.div
        ref={ref}
        className={className}
        initial="hidden"
        animate={isInView ? 'visible' : 'hidden'}
        variants={variants}
        transition={transition}
        {...props}
      >
        {React.Children.map(children, (child, index) => {
          if (React.isValidElement(child)) {
            return React.cloneElement(child as React.ReactElement<Record<string, unknown>>, {
              variants: staggerItemVariants,
              custom: index,
            });
          }
          return child;
        })}
      </motion.div>
    );
  }

  // For individual child animations
  const animationProps = {
    ref,
    className,
    initial: shouldAnimate && !hasAnimated ? 'hidden' : false,
    animate: isInView || (once && hasAnimated) ? 'visible' : 'hidden',
    variants,
    transition,
    ...props,
  };

  // Apply subtle variant (reduced intensity)
  if (subtle) {
    const subtleVariants = {
      hidden: { opacity: 0, y: 15 },
      visible: { opacity: 1, y: 0 },
    };
    return (
      <motion.div
        {...animationProps}
        variants={subtleVariants}
        transition={{ duration: duration * 0.8, delay, ease: 'easeOut' }}
      >
        {children}
      </motion.div>
    );
  }

  return (
    <motion.div {...animationProps}>
      {children}
    </motion.div>
  );
}

// ============================================================
// ScrollRevealGroup ΓÇô Group multiple items with stagger
// ============================================================
export interface ScrollRevealGroupProps extends Omit<ScrollRevealProps, 'variant' | 'children'> {
  children: React.ReactNode;
  /**
   * The stagger direction
   * @default 'up'
   */
  direction?: 'up' | 'down' | 'left' | 'right' | 'fade';
  /**
   * The number of columns for grid layout
   */
  columns?: 2 | 3 | 4 | 5;
  /**
   * Gap between items
   * @default 'gap-4 md:gap-6'
   */
  gap?: string;
}

export function ScrollRevealGroup({
  children,
  direction = 'up',
  columns,
  gap = 'gap-4 md:gap-6',
  duration = 0.5,
  staggerChildren = 0.08,
  threshold = 0.15,
  once = true,
  className,
  ...props
}: ScrollRevealGroupProps) {
  // Map direction to variant
  const variantMap: Record<string, RevealVariant> = {
    up: 'fadeUp',
    down: 'fadeDown',
    left: 'fadeLeft',
    right: 'fadeRight',
    fade: 'fade',
  };

  const columnClasses = columns
    ? {
        2: 'grid-cols-1 sm:grid-cols-2',
        3: 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3',
        4: 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-4',
        5: 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-5',
      }[columns]
    : '';

  return (
    <ScrollReveal
      variant="stagger"
      duration={duration}
      staggerChildren={staggerChildren}
      threshold={threshold}
      once={once}
      className={cn('grid', columnClasses, gap, className)}
      {...props}
    >
      {React.Children.map(children, (child, index) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child as React.ReactElement<Record<string, unknown>>, {
            variants: {
              hidden: { opacity: 0, y: 20 },
              visible: {
                opacity: 1,
                y: 0,
                transition: {
                  duration: 0.5,
                  delay: index * 0.08,
                  ease: 'easeOut',
                },
              },
            },
          });
        }
        return child;
      })}
    </ScrollReveal>
  );
}

// ============================================================
// ScrollRevealItem ΓÇô Individual item in a group
// ============================================================
export interface ScrollRevealItemProps extends Omit<ScrollRevealProps, 'children'> {
  children: React.ReactNode;
  index?: number;
}

export function ScrollRevealItem({
  children,
  index = 0,
  duration = 0.5,
  delay = 0,
  className,
  ...props
}: ScrollRevealItemProps) {
  const itemDelay = delay + index * 0.05;

  return (
    <ScrollReveal
      duration={duration}
      delay={itemDelay}
      className={className}
      {...props}
    >
      {children}
    </ScrollReveal>
  );
}

// ============================================================
// ScrollRevealSection ΓÇô Full section with title and content
// ============================================================
export interface ScrollRevealSectionProps extends ScrollRevealProps {
  title?: string;
  titleVariant?: RevealVariant;
  subtitle?: string;
  align?: 'left' | 'center' | 'right';
  children: React.ReactNode;
}

export function ScrollRevealSection({
  title,
  titleVariant = 'fadeUp',
  subtitle,
  align = 'center',
  children,
  className,
  ...props
}: ScrollRevealSectionProps) {
  const alignClasses = {
    left: 'text-left items-start',
    center: 'text-center items-center',
    right: 'text-right items-end',
  };

  return (
    <div className={cn('space-y-6', className)}>
      {/* Header */}
      {(title || subtitle) && (
        <div className={cn('flex flex-col', alignClasses[align])}>
          {title && (
            <ScrollReveal variant={titleVariant} once threshold={0.1}>
              <h2 className="font-cinzel text-2xl md:text-3xl font-bold text-brown dark:text-ivory">
                {title}
              </h2>
            </ScrollReveal>
          )}
          {subtitle && (
            <ScrollReveal variant="fade" delay={0.1} once threshold={0.1}>
              <p className={cn(
                'text-brown-light dark:text-ivory/60 text-sm md:text-base max-w-2xl',
                align === 'center' && 'mx-auto'
              )}>
                {subtitle}
              </p>
            </ScrollReveal>
          )}
        </div>
      )}

      {/* Content */}
      <ScrollReveal {...props}>
        {children}
      </ScrollReveal>
    </div>
  );
}

// ============================================================
// ScrollRevealImage ΓÇô Specialized image reveal with zoom
// ============================================================
export interface ScrollRevealImageProps extends ScrollRevealProps {
  src: string;
  alt: string;
  aspectRatio?: '1/1' | '4/3' | '16/9' | '21/9' | '3/2';
  className?: string;
}

export function ScrollRevealImage({
  src,
  alt,
  aspectRatio = '16/9',
  className,
  variant = 'scale',
  ...props
}: ScrollRevealImageProps) {
  const aspectRatioClasses = {
    '1/1': 'aspect-square',
    '4/3': 'aspect-[4/3]',
    '16/9': 'aspect-[16/9]',
    '21/9': 'aspect-[21/9]',
    '3/2': 'aspect-[3/2]',
  };

  return (
    <ScrollReveal variant={variant} {...props}>
      <div className={cn('relative overflow-hidden rounded-2xl', aspectRatioClasses[aspectRatio], className)}>
        <img
          src={src}
          alt={alt}
          className="w-full h-full object-cover"
          loading="lazy"
        />
      </div>
    </ScrollReveal>
  );
}

// ============================================================
// ScrollRevealList ΓÇô For animating list items
// ============================================================
export interface ScrollRevealListProps extends Omit<ScrollRevealGroupProps, 'children' | 'columns'> {
  items: Array<{
    id: string;
    content: React.ReactNode;
  }>;
  columns?: 1 | 2 | 3 | 4;
}

export function ScrollRevealList({
  items,
  columns = 1,
  gap = 'gap-4',
  ...props
}: ScrollRevealListProps) {
  const columnClasses = {
    1: 'grid-cols-1',
    2: 'grid-cols-1 sm:grid-cols-2',
    3: 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3',
    4: 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-4',
  };

  return (
    <div className={cn('grid', columnClasses[columns as keyof typeof columnClasses] || 'grid-cols-1', gap)}>
      {items.map((item, index) => (
        <ScrollRevealItem key={item.id} index={index} {...props}>
          {item.content}
        </ScrollRevealItem>
      ))}
    </div>
  );
}

// ============================================================
// ScrollRevealSkeleton ΓÇô Loading placeholder
// ============================================================
export interface ScrollRevealSkeletonProps {
  count?: number;
  height?: number;
  width?: string;
  className?: string;
  variant?: 'rect' | 'circle' | 'text';
}

export function ScrollRevealSkeleton({
  count = 3,
  height = 200,
  width = 'w-full',
  className,
  variant = 'rect',
}: ScrollRevealSkeletonProps) {
  const variantClasses = {
    rect: 'rounded-2xl',
    circle: 'rounded-full aspect-square',
    text: 'rounded-lg h-6',
  };

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6">
      {Array.from({ length: count }).map((_, i) => (
        <div
          key={i}
          className={cn(
            'bg-sand/50 dark:bg-brown/50 animate-pulse',
            variantClasses[variant],
            className
          )}
          style={{ height: variant === 'text' ? 'auto' : height, minHeight: variant === 'text' ? 24 : 0 }}
        />
      ))}
    </div>
  );
}

// ============================================================
// useScrollReveal ΓÇô Custom hook for programmatic control
// ============================================================
export function useScrollReveal<T extends HTMLElement = HTMLDivElement>() {
  const ref = useRef<T>(null);
  const isInView = useInView(ref, { amount: 0.2, once: true });
  const [isVisible, setIsVisible] = useState(false);

  // Derive isVisible during render instead of in an effect, to avoid the
  // extra render pass caused by setState-in-effect.
  if (isInView && !isVisible) {
    setIsVisible(true);
  }

  return { ref, isInView, isVisible };
}

