              )}
            </div>
          )}

          {/* Footer */}
          <div className="flex items-center justify-between mt-4 pt-3 border-t border-gold/10 dark:border-gold/5">
            <div className="flex items-center gap-3 text-xs text-brown-light dark:text-ivory/50">
