                <span className="flex items-center gap-1.5">
                  {authorAvatar ? (
                    <Image
                      src={authorAvatar}
                      alt={author}
                      width={18}
                      height={18}
                      className="rounded-full"
                    />
                  ) : (
                    <User className="w-3 h-3" />
