            width: 8px;
            height: 8px;
            border-radius: 50%;
            transition: all 0.3s;
          }
          .swiper-pagination-bullet-active {
            opacity: 1;
            width: 24px;
            border-radius: 4px;
            background: #D4AF37;
          }
          .swiper-button-prev-custom,
          .swiper-button-next-custom {
            display: none;
          }
