  // Slider mode
  return (
    <section
      ref={sectionRef}
      className={cn('py-12 md:py-16 bg-ivory dark:bg-brown overflow-hidden', className)}
    >
      <Container>
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={isInView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.6 }}
          className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8"
        >
          <div>
            <div className="ornate-divider">
              <span className="diamond">Γ£ª</span>
            </div>
            <h2 className="font-cinzel text-2xl md:text-3xl font-bold text-brown dark:text-ivory">
              {title}
            </h2>
            {subtitle && (
              <p className="text-brown-light dark:text-ivory/60 text-sm mt-1">
                {subtitle}
              </p>
            )}
          </div>
          <a
            href="https://youtube.com/@panditjimurti"
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center gap-2 text-sm font-medium text-gold-dark dark:text-gold hover:text-gold transition-colors group"
          >
            <span className="text-xl">≡ƒÄÑ</span>
            Visit Channel
            <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
          </a>
        </motion.div>

        {/* Swiper Slider */}
        <div className="relative">
          <Swiper
            modules={[Navigation, Pagination, Autoplay, A11y]}
            spaceBetween={20}
            slidesPerView={slidesPerView}
            breakpoints={breakpoints}
            navigation={{
              nextEl: '.swiper-button-next-custom',
              prevEl: '.swiper-button-prev-custom',
            }}
            pagination={{
              clickable: true,
              dynamicBullets: true,
            }}
            autoplay={{
              delay: autoplayDelay,
              disableOnInteraction: false,
              pauseOnMouseEnter: true,
            }}
            loop={videos.length > (slidesPerView || 3)}
            grabCursor
            className="!overflow-visible"
          >
            {videos.map((video, index) => (
              <SwiperSlide key={video.id}>
                <VideoCard video={video} index={index} />
              </SwiperSlide>
            ))}
          </Swiper>

          {/* Custom Navigation Buttons */}
          {isMounted && videos.length > (slidesPerView || 3) && (
            <>
              <button
                className="swiper-button-prev-custom absolute left-0 top-1/2 -translate-y-1/2 z-10 -translate-x-1/2 md:-translate-x-4 w-10 h-10 md:w-12 md:h-12 rounded-full bg-white dark:bg-brown-dark shadow-lg hover:shadow-xl transition-all flex items-center justify-center text-brown dark:text-ivory hover:text-gold-dark dark:hover:text-gold border border-gold/10"
                aria-label="Previous videos"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <button
                className="swiper-button-next-custom absolute right-0 top-1/2 -translate-y-1/2 z-10 translate-x-1/2 md:translate-x-4 w-10 h-10 md:w-12 md:h-12 rounded-full bg-white dark:bg-brown-dark shadow-lg hover:shadow-xl transition-all flex items-center justify-center text-brown dark:text-ivory hover:text-gold-dark dark:hover:text-gold border border-gold/10"
                aria-label="Next videos"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </>
          )}
        </div>
      </Container>

      {/* Custom styles for Swiper */}
      <style>{`
        .swiper-pagination {
          position: relative;
          margin-top: 24px;
        }
        .swiper-pagination-bullet {
          background: #D4AF37;
          opacity: 0.3;
          width: 8px;
          height: 8px;
          border-radius: 50%;
          transition: all 0.3s;
        }
        .swiper-pagination-bullet-active {
          opacity: 1;
          width: 24px;
          border-radius: 4px;
          background: #D4AF37;
        }
        .swiper-button-prev-custom,
        .swiper-button-next-custom {
          display: none;
        }
        @media (min-width: 768px) {
          .swiper-button-prev-custom,
          .swiper-button-next-custom {
            display: flex;
          }
        }
        .swiper-button-prev-custom.swiper-button-disabled,
        .swiper-button-next-custom.swiper-button-disabled {
          opacity: 0.3;
          cursor: not-allowed;
        }
      `}</style>
    </section>
  );
}

// frontend/src/components/ui/Select.tsx

'use client';

import * as React from 'react';
import * as SelectPrimitive from '@radix-ui/react-select';
import { Check, ChevronDown, ChevronUp, X } from 'lucide-react';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';

// ============================================================
// Select Variants
// ============================================================
const selectTriggerVariants = cva(
  // Base styles
  'flex w-full items-center justify-between rounded-xl border bg-white dark:bg-brown-dark text-brown dark:text-ivory placeholder:text-brown-light/50 dark:placeholder:text-ivory/30 transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gold/30 focus-visible:ring-offset-2 focus-visible:ring-offset-white disabled:cursor-not-allowed disabled:opacity-50 [&>span]:line-clamp-1',
  {
    variants: {
      variant: {
        default: 'border-gold/20 focus:border-gold focus:ring-gold/20',
        error: 'border-red-500 focus:border-red-500 focus:ring-red-500/20',
        success: 'border-green-500 focus:border-green-500 focus:ring-green-500/20',
        ghost: 'border-transparent bg-sand/30 dark:bg-brown/30 focus:border-gold',
      },
      size: {
        sm: 'h-9 px-3 text-sm',
        md: 'h-10 px-4 text-sm',
        lg: 'h-12 px-5 text-base',
        xl: 'h-14 px-6 text-base',
      },
      rounded: {
        none: 'rounded-none',
        sm: 'rounded-lg',
        default: 'rounded-xl',
        lg: 'rounded-2xl',
        full: 'rounded-full',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'md',
      rounded: 'default',
    },
  }
);

// ============================================================
// Types
// ============================================================
export interface SelectOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export interface SelectProps
  extends Omit<React.ComponentPropsWithoutRef<typeof SelectPrimitive.Root>, 'value' | 'onValueChange'>,
    VariantProps<typeof selectTriggerVariants> {
  /** Additional className applied to the trigger element */
  className?: string;
  /** Label for the select */
  label?: string;
  /** Label className */
  labelClassName?: string;
  /** Error message */
  error?: string;
  /** Success message */
  success?: string;
  /** Help text */
  helpText?: string;
  /** Whether the select is required */
  required?: boolean;
  /** Placeholder text when no value is selected */
  placeholder?: string;
  /** Options array */
  options?: SelectOption[];
  /** Value of the select (controlled) */
  value?: string;
  /** Default value (uncontrolled) */
  defaultValue?: string;
  /** Callback when value changes */
  onValueChange?: (value: string) => void;
  /** Left icon */
  leftIcon?: React.ReactNode;
  /** Container className */
  containerClassName?: string;
  /** Trigger className */
  triggerClassName?: string;
  /** Content className */
  contentClassName?: string;
  /** Loading state */
  loading?: boolean;
}

// ============================================================
// Select Components
// ============================================================
const Select = React.forwardRef<HTMLButtonElement, SelectProps>(
  (
    {
      className,
      containerClassName,
      triggerClassName,
      contentClassName,
      label,
      labelClassName,
      error,
      success,
      helpText,
      required = false,
      placeholder = 'Select an option',
      options = [],
      variant,
      size,
      rounded,
      leftIcon,
      value,
      defaultValue,
      onValueChange,
      disabled = false,
      loading = false,
      children,
      ...props
    },
    ref
  ) => {
    // Determine variant based on error/success
    let triggerVariant = variant;
    if (error) {
      triggerVariant = 'error';
    } else if (success) {
      triggerVariant = 'success';
    }

    // Generate unique ID
    const id = React.useId();

    // If children are provided, use them; otherwise render from options
    const triggerContent = children ? (
      children
    ) : (
      <SelectPrimitive.Value placeholder={placeholder} />
    );

    return (
      <div className={cn('w-full space-y-1.5', containerClassName)}>
        {/* Label */}
        {label && (
          <label
            htmlFor={id}
            className={cn(
              'block text-sm font-medium text-brown dark:text-ivory',
              labelClassName,
              required && 'after:content-["*"] after:ml-1 after:text-red-500'
            )}
          >
            {label}
          </label>
        )}

        <SelectPrimitive.Root
          value={value}
          defaultValue={defaultValue}
          onValueChange={onValueChange}
          disabled={disabled || loading}
          {...props}
        >
          <SelectPrimitive.Trigger
            ref={ref}
            id={id}
            className={cn(
              selectTriggerVariants({ variant: triggerVariant, size, rounded }),
              leftIcon && 'pl-10',
              loading && 'pr-12',
              triggerClassName,
              className
            )}
            aria-invalid={!!error}
            aria-describedby={
              error ? `${id}-error` : helpText ? `${id}-help` : undefined
            }
          >
            {leftIcon && (
              <span className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none text-brown-light/50 dark:text-ivory/30">
                {leftIcon}
              </span>
            )}
            <SelectPrimitive.Value placeholder={placeholder} />
            <SelectPrimitive.Icon asChild>
              <ChevronDown className="h-4 w-4 opacity-50" />
            </SelectPrimitive.Icon>
          </SelectPrimitive.Trigger>

          <SelectPrimitive.Portal>
            <SelectPrimitive.Content
              className={cn(
                'relative z-50 max-h-96 min-w-[8rem] overflow-hidden rounded-xl border border-gold/10 bg-white dark:bg-brown-dark shadow-lg shadow-black/5 animate-in fade-in-80',
                contentClassName
              )}
              position="popper"
              sideOffset={4}
            >
              <SelectPrimitive.ScrollUpButton className="flex h-8 items-center justify-center text-brown-light">
                <ChevronUp className="h-4 w-4" />
              </SelectPrimitive.ScrollUpButton>

              <SelectPrimitive.Viewport className="p-1">
                {options.length > 0 ? (
                  options.map((option) => (
                    <SelectItem
                      key={option.value}
                      value={option.value}
                      disabled={option.disabled}
                      className="cursor-pointer"
                    >
                      {option.label}
                    </SelectItem>
                  ))
                ) : (
                  <div className="py-2 text-center text-sm text-brown-light/50">
                    No options available
                  </div>
                )}
              </SelectPrimitive.Viewport>

              <SelectPrimitive.ScrollDownButton className="flex h-8 items-center justify-center text-brown-light">
                <ChevronDown className="h-4 w-4" />
              </SelectPrimitive.ScrollDownButton>
            </SelectPrimitive.Content>
          </SelectPrimitive.Portal>
        </SelectPrimitive.Root>

        {/* Error message */}
        {error && (
          <p
            id={`${id}-error`}
            className="text-xs text-red-500 flex items-center gap-1 mt-1"
          >
            <span className="inline-block w-1 h-1 rounded-full bg-red-500" />
            {error}
          </p>
        )}

        {/* Success message */}
        {success && !error && (
          <p className="text-xs text-green-500 flex items-center gap-1 mt-1">
            <span className="inline-block w-1 h-1 rounded-full bg-green-500" />
            {success}
          </p>
        )}

        {/* Help text */}
        {helpText && !error && !success && (
          <p id={`${id}-help`} className="text-xs text-brown-light/60 dark:text-ivory/40 mt-1">
            {helpText}
          </p>
        )}
      </div>
    );
  }
);

Select.displayName = 'Select';

// ============================================================
// SelectItem Component
// ============================================================
export interface SelectItemProps
  extends React.ComponentPropsWithoutRef<typeof SelectPrimitive.Item> {
  /** Additional className */
  className?: string;
  /** Children */
  children: React.ReactNode;
}

const SelectItem = React.forwardRef<HTMLDivElement, SelectItemProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <SelectPrimitive.Item
        ref={ref}
        className={cn(
          'relative flex w-full cursor-pointer select-none items-center rounded-lg py-1.5 pl-8 pr-3 text-sm text-brown dark:text-ivory outline-none transition-colors focus:bg-gold/10 data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
          className
        )}
        {...props}
      >
        <span className="absolute left-2 flex h-3.5 w-3.5 items-center justify-center">
          <SelectPrimitive.ItemIndicator>
            <Check className="h-4 w-4 text-gold-dark dark:text-gold" />
          </SelectPrimitive.ItemIndicator>
        </span>
        <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
      </SelectPrimitive.Item>
    );
  }
);
SelectItem.displayName = 'SelectItem';

// ============================================================
// SelectGroup Component
// ============================================================
const SelectGroup = SelectPrimitive.Group;
const SelectLabel = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Label>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.Label
    ref={ref}
    className={cn('px-2 py-1.5 text-xs font-semibold text-brown-light/70 dark:text-ivory/50', className)}
    {...props}
  />
));
SelectLabel.displayName = 'SelectLabel';

const SelectSeparator = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.Separator
    ref={ref}
    className={cn('-mx-1 my-1 h-px bg-gold/10 dark:bg-gold/5', className)}
    {...props}
  />
));
SelectSeparator.displayName = 'SelectSeparator';

// ============================================================
// Exports
// ============================================================
export {
  Select,
  SelectItem,
  SelectGroup,
  SelectLabel,
  SelectSeparator,
  selectTriggerVariants,
};

export default Select;

// frontend/src/features/auth/api/authApi.ts

import { apiClient } from '@/services/apiClient';
import type {
  AuthResponse,
  LoginCredentials,
  RegisterData,
  SocialAuthData,
  VerifyOTPData,
  ResetPasswordData,
  ChangePasswordData,
  UpdateProfileData,
  User,
  SessionData,
  AuthError,
} from '@/features/auth/types/auth.types';

// ============================================================
// Query Keys (for React Query)
// ============================================================
export const authQueryKeys = {
  all: ['auth'] as const,
  session: () => [...authQueryKeys.all, 'session'] as const,
  user: () => [...authQueryKeys.all, 'user'] as const,
  profile: () => [...authQueryKeys.all, 'profile'] as const,
  permissions: () => [...authQueryKeys.all, 'permissions'] as const,
};

// ============================================================
// Auth API
// ============================================================
export const authApi = {
  // ============================================================
  // Registration
  // ============================================================

  /**
   * Register a new user
   * 
   * @param data - Registration data
   * @returns AuthResponse with user and tokens
   * 
   * @example
   * ```ts
   * const response = await authApi.register({
   *   name: 'Devotee Sharma',
   *   email: 'devotee@example.com',
   *   phone: '+917240364772',
   *   password: 'SecurePassword123',
   *   confirmPassword: 'SecurePassword123',
   * });
   * ```
   */
  register: async (data: RegisterData): Promise<AuthResponse> => {
    const response = await apiClient.post<AuthResponse>('/auth/register', data);
    return response.data;
  },

  /**
   * Verify email with OTP
   */
  verifyEmail: async (email: string, otp: string): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/verify-email', { email, otp });
    return response.data;
  },

  /**
   * Resend verification OTP
   */
  resendVerificationOTP: async (email: string): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/resend-otp', { email });
    return response.data;
  },

  // ============================================================
  // Login & Authentication
  // ============================================================

  /**
   * Login with email and password
   * 
   * @param credentials - Email and password
   * @returns AuthResponse with user and tokens
   * 
   * @example
   * ```ts
   * const response = await authApi.login({
   *   email: 'devotee@example.com',
   *   password: 'SecurePassword123',
   * });
   * ```
   */
  login: async (credentials: LoginCredentials): Promise<AuthResponse> => {
    const response = await apiClient.post<AuthResponse>('/auth/login', credentials);
    return response.data;
  },

  /**
   * Login with phone number and OTP
   */
  loginWithPhone: async (phone: string, otp: string): Promise<AuthResponse> => {
    const response = await apiClient.post<AuthResponse>('/auth/login/phone', { phone, otp });
    return response.data;
  },

  /**
   * Send OTP for phone login
   */
  sendPhoneOTP: async (phone: string): Promise<{ success: boolean; message: string; expiresIn: number }> => {
    const response = await apiClient.post('/auth/send-otp', { phone });
    return response.data;
  },

  /**
   * Social login with Google, Facebook, etc.
   */
  socialLogin: async (data: SocialAuthData): Promise<AuthResponse> => {
    const response = await apiClient.post<AuthResponse>('/auth/social-login', data);
    return response.data;
  },

  /**
   * Get current session user
   */
  getSession: async (): Promise<User> => {
    const response = await apiClient.get<User>('/auth/session');
    return response.data;
  },

  /**
   * Validate session token
   */
  validateSession: async (): Promise<SessionData> => {
    const response = await apiClient.get<SessionData>('/auth/validate');
    return response.data;
  },

  // ============================================================
  // Token Management
  // ============================================================

  /**
   * Refresh access token using refresh token
   */
  refreshToken: async (refreshToken: string): Promise<{ accessToken: string; refreshToken: string }> => {
    const response = await apiClient.post('/auth/refresh-token', { refreshToken });
    return response.data;
  },

  /**
   * Logout (invalidate refresh token)
   */
  logout: async (): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/logout');
    return response.data;
  },

  /**
   * Logout from all devices
   */
  logoutAll: async (): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/logout-all');
    return response.data;
  },

  // ============================================================
  // Password Management
  // ============================================================

  /**
   * Request password reset (send reset link to email)
   */
  forgotPassword: async (email: string): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/forgot-password', { email });
    return response.data;
  },

  /**
   * Reset password using token
   */
  resetPassword: async (data: ResetPasswordData): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/reset-password', data);
    return response.data;
  },

  /**
   * Change password (requires authentication)
   */
  changePassword: async (data: ChangePasswordData): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/change-password', data);
    return response.data;
  },

  // ============================================================
  // Profile Management
  // ============================================================

  /**
   * Get user profile
   */
  getProfile: async (): Promise<User> => {
    const response = await apiClient.get<User>('/auth/profile');
    return response.data;
  },

  /**
   * Update user profile
   */
  updateProfile: async (data: UpdateProfileData): Promise<User> => {
    const response = await apiClient.put<User>('/auth/profile', data);
    return response.data;
  },

  /**
   * Update profile picture (avatar)
   */
  updateAvatar: async (file: File): Promise<{ avatarUrl: string }> => {
    const formData = new FormData();
    formData.append('avatar', file);
    const response = await apiClient.put('/auth/profile/avatar', formData, {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    });
    return response.data;
  },

  /**
   * Delete profile picture
   */
  deleteAvatar: async (): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.delete('/auth/profile/avatar');
    return response.data;
  },

  // ============================================================
  // User Management (authenticated users)
  // ============================================================

  /**
   * Get all users (admin only)
   */
  getUsers: async (params?: { page?: number; limit?: number; role?: string; search?: string }): Promise<{
    users: User[];
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  }> => {
    const queryParams = new URLSearchParams();
    if (params?.page) queryParams.append('page', String(params.page));
    if (params?.limit) queryParams.append('limit', String(params.limit));
    if (params?.role) queryParams.append('role', params.role);
    if (params?.search) queryParams.append('search', params.search);

    const url = queryParams.toString() ? `/users?${queryParams}` : '/users';
    const response = await apiClient.get(url);
    return response.data;
  },

  /**
   * Get user by ID (admin only)
   */
  getUserById: async (userId: string): Promise<User> => {
    const response = await apiClient.get<User>(`/users/${userId}`);
    return response.data;
  },

  /**
   * Update user role (admin only)
   */
  updateUserRole: async (userId: string, role: string): Promise<User> => {
    const response = await apiClient.put<User>(`/users/${userId}/role`, { role });
    return response.data;
  },

  /**
   * Delete user (admin only)
   */
  deleteUser: async (userId: string): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.delete(`/users/${userId}`);
    return response.data;
  },

  // ============================================================
  // Two-Factor Authentication
  // ============================================================

  /**
   * Enable 2FA for the current user
   */
  enable2FA: async (): Promise<{ qrCode: string; secret: string; backupCodes: string[] }> => {
    const response = await apiClient.post('/auth/2fa/enable');
    return response.data;
  },

  /**
   * Verify 2FA code
   */
  verify2FA: async (code: string): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/2fa/verify', { code });
    return response.data;
  },

  /**
   * Disable 2FA
   */
  disable2FA: async (code: string): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/2fa/disable', { code });
    return response.data;
  },

  // ============================================================
  // Email Management
  // ============================================================

  /**
   * Change email (requires authentication)
   */
  changeEmail: async (newEmail: string, password: string): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/change-email', { newEmail, password });
    return response.data;
  },

  /**
   * Verify new email
   */
  verifyNewEmail: async (otp: string): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.post('/auth/verify-new-email', { otp });
    return response.data;
  },

  // ============================================================
  // Device Management
  // ============================================================

  /**
   * Get all active sessions/devices
   */
  getActiveSessions: async (): Promise<Array<{
    deviceId: string;
    deviceName: string;
    browser: string;
    os: string;
    ip: string;
    lastActive: string;
    isCurrent: boolean;
  }>> => {
    const response = await apiClient.get('/auth/sessions');
    return response.data;
  },

  /**
   * Terminate a specific session
   */
  terminateSession: async (sessionId: string): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.delete(`/auth/sessions/${sessionId}`);
    return response.data;
  },

  /**
   * Terminate all sessions except current
   */
  terminateAllSessions: async (): Promise<{ success: boolean; message: string }> => {
    const response = await apiClient.delete('/auth/sessions/all');
    return response.data;
  },

  // ============================================================
  // Admin/Dev Tools
  // ============================================================

  /**
   * Check if email is available (for registration)
   */
  checkEmailAvailability: async (email: string): Promise<{ available: boolean; message?: string }> => {
    const response = await apiClient.get(`/auth/check-email?email=${encodeURIComponent(email)}`);
    return response.data;
  },

  /**
   * Check if phone is available (for registration)
   */
  checkPhoneAvailability: async (phone: string): Promise<{ available: boolean; message?: string }> => {
    const response = await apiClient.get(`/auth/check-phone?phone=${encodeURIComponent(phone)}`);
    return response.data;
  },

  /**
   * Get user permissions (for RBAC)
   */
  getPermissions: async (): Promise<string[]> => {
    const response = await apiClient.get<string[]>('/auth/permissions');
    return response.data;
  },
};

// ============================================================
// Utility Functions
// ============================================================

/**
 * Extract error message from API error
 */
export function getAuthErrorMessage(error: unknown): string {
  if (error && typeof error === 'object' && 'response' in error) {
    const axiosError = error as any;
    if (axiosError.response?.data?.message) {
      return axiosError.response.data.message;
    }
    if (axiosError.response?.data?.errors) {
      const errors = axiosError.response.data.errors;
      if (Array.isArray(errors)) {
        return errors.map((e: any) => e.message || e).join(', ');
      }
      return Object.values(errors).flat().join(', ');
    }
  }
  if (error instanceof Error) {
    return error.message;
  }
  return 'An unexpected error occurred';
}

/**
 * Check if a token is expired
 */
export function isTokenExpired(token: string): boolean {
  try {
    const payload = JSON.parse(atob(token.split('.')[1]));
    const exp = payload.exp;
    if (!exp) return true;
    return Date.now() >= exp * 1000;
  } catch {
    return true;
  }
}

/**
 * Decode JWT token
 */
export function decodeToken(token: string): any {
  try {
    return JSON.parse(atob(token.split('.')[1]));
  } catch {
    return null;
  }
}

/**
 * Get token expiration time in milliseconds
 */
export function getTokenExpiry(token: string): number | null {
  try {
    const payload = JSON.parse(atob(token.split('.')[1]));
    return payload.exp ? payload.exp * 1000 : null;
  } catch {
    return null;
  }
}

/**
 * Check if token is about to expire (within 5 minutes)
 */
export function isTokenExpiringSoon(token: string, thresholdMs: number = 5 * 60 * 1000): boolean {
  const expiry = getTokenExpiry(token);
  if (!expiry) return true;
  return Date.now() >= expiry - thresholdMs;
}

// ============================================================
// React Query Invalidation Helpers
// ============================================================

/**
 * Invalidate all auth queries
 */
export function invalidateAuthQueries(queryClient: any): void {
  queryClient.invalidateQueries({ queryKey: authQueryKeys.all });
}

/**
 * Invalidate session data
 */
export function invalidateSession(queryClient: any): void {
  queryClient.invalidateQueries({ queryKey: authQueryKeys.session() });
}

/**
 * Invalidate user profile
 */
export function invalidateProfile(queryClient: any): void {
  queryClient.invalidateQueries({ queryKey: authQueryKeys.profile() });
}

