import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { immer } from 'zustand/middleware/immer';
import { toast } from 'react-hot-toast';

import type { Product } from '@/features/products/types/product.types';

// ============================================================
// Types
// ============================================================

/**
 * Cart item structure
 */
export interface CartItem {
  product: Product;
  quantity: number;
}

/**
 * Applied coupon
 */
export interface AppliedCoupon {
  code: string;
  discountType: 'percentage' | 'fixed';
  discountValue: number;
  description?: string;
}

/**
 * Cart state interface
 */
export interface CartState {
  // Items
  items: CartItem[];

  // Coupon
  coupon: AppliedCoupon | null;

  // Gift wrap option
  giftWrap: boolean;

  // Shipping method
  shippingMethod: 'standard' | 'express';

  // Computed totals (derived)
  totalItems: number;
  totalPrice: number;
  subtotal: number;
  shippingCost: number;
  tax: number;
  discountAmount: number;
  grandTotal: number;

  // Actions
  addItem: (product: Product, quantity?: number) => void;
  removeItem: (productId: string) => void;
  updateQuantity: (productId: string, quantity: number) => void;
  clearCart: () => void;

  // Coupon actions
  applyCoupon: (code: string) => Promise<boolean>;
  removeCoupon: () => void;

  // Shipping actions
  setShippingMethod: (method: 'standard' | 'express') => void;

  // Gift wrap actions
  toggleGiftWrap: () => void;

  // Utility actions
  isInCart: (productId: string) => boolean;
  getItemQuantity: (productId: string) => number;
  getItem: (productId: string) => CartItem | undefined;

  // Checkout
  prepareCheckout: () => {
    items: CartItem[];
    subtotal: number;
    shippingCost: number;
    tax: number;
    discountAmount: number;
    grandTotal: number;
    coupon: AppliedCoupon | null;
    giftWrap: boolean;
    shippingMethod: 'standard' | 'express';
  };

  // Reset
  reset: () => void;
}

// ============================================================
// Constants
// ============================================================

const TAX_RATE = 0.18; // 18% GST
const FREE_SHIPPING_THRESHOLD = 5000; // Free shipping above Γé╣5,000
const STANDARD_SHIPPING_COST = 299;
const EXPRESS_SHIPPING_COST = 499;

// ============================================================
// Initial state
// ============================================================

const initialState = {
  items: [],
  coupon: null,
  giftWrap: false,
  shippingMethod: 'standard' as const,
  totalItems: 0,
  totalPrice: 0,
  subtotal: 0,
  shippingCost: 0,
  tax: 0,
  discountAmount: 0,
  grandTotal: 0,
};

// ============================================================
// Helper functions
// ============================================================

/**
 * Calculate shipping cost based on subtotal and method
 */
const calculateShippingCost = (subtotal: number, method: 'standard' | 'express'): number => {
  if (subtotal >= FREE_SHIPPING_THRESHOLD) {
    return 0;
  }
  return method === 'standard' ? STANDARD_SHIPPING_COST : EXPRESS_SHIPPING_COST;
};

/**
 * Calculate tax (GST)
 */
const calculateTax = (subtotal: number): number => {
  return Math.round(subtotal * TAX_RATE);
};

/**
 * Calculate discount amount from coupon
 */
const calculateDiscount = (subtotal: number, coupon: AppliedCoupon | null): number => {
  if (!coupon) return 0;
  if (coupon.discountType === 'percentage') {
    return Math.round((subtotal * coupon.discountValue) / 100);
  }
  return Math.min(coupon.discountValue, subtotal);
};

/**
 * Calculate all totals
 */
const calculateTotals = (
  items: CartItem[],
  coupon: AppliedCoupon | null,
  shippingMethod: 'standard' | 'express',
  giftWrap: boolean
) => {
  const subtotal = items.reduce((sum, item) => sum + item.product.price * item.quantity, 0);
  const totalItems = items.reduce((sum, item) => sum + item.quantity, 0);
  const shippingCost = calculateShippingCost(subtotal, shippingMethod);
  const tax = calculateTax(subtotal);
  const discountAmount = calculateDiscount(subtotal, coupon);
  const giftWrapCost = giftWrap ? 99 : 0;
  const grandTotal = subtotal + shippingCost + tax + giftWrapCost - discountAmount;

  return {
    subtotal,
    totalItems,
    shippingCost,
    tax,
    discountAmount,
    grandTotal,
    giftWrapCost,
  };
};

