// ============================================================
// Zustand Store with persistence
// ============================================================

export const useCartStore = create<CartState>()(
  persist(
    immer((set, get) => ({
      // === Initial state ===
      ...initialState,

      // === Add item ===
      addItem: (product: Product, quantity: number = 1) => {
        set((state) => {
          const existingItem = state.items.find((item: CartItem) => item.product.id === product.id);

          if (existingItem) {
            existingItem.quantity += quantity;
          } else {
            state.items.push({ product, quantity });
          }

          // Recalculate totals
          const totals = calculateTotals(
            state.items,
            state.coupon,
            state.shippingMethod,
            state.giftWrap
          );

          state.subtotal = totals.subtotal;
          state.totalItems = totals.totalItems;
          state.shippingCost = totals.shippingCost;
          state.tax = totals.tax;
          state.discountAmount = totals.discountAmount;
          state.grandTotal = totals.grandTotal;
          state.totalPrice = totals.subtotal;
        });

        // Toast notification
        toast.success(`${product.name} added to cart Γ£¿`);
      },

      // === Remove item ===
      removeItem: (productId: string) => {
        set((state) => {
          const item = state.items.find((i: CartItem) => i.product.id === productId);
          state.items = state.items.filter((item: CartItem) => item.product.id !== productId);

          // Recalculate totals
          const totals = calculateTotals(
            state.items,
            state.coupon,
            state.shippingMethod,
            state.giftWrap
          );

          state.subtotal = totals.subtotal;
          state.totalItems = totals.totalItems;
          state.shippingCost = totals.shippingCost;
          state.tax = totals.tax;
          state.discountAmount = totals.discountAmount;
          state.grandTotal = totals.grandTotal;
          state.totalPrice = totals.subtotal;
        });

        toast.success('Item removed from cart');
      },

      // === Update quantity ===
      updateQuantity: (productId: string, quantity: number) => {
        if (quantity <= 0) {
          get().removeItem(productId);
          return;
        }

        set((state) => {
          const item = state.items.find((i: CartItem) => i.product.id === productId);
          if (item) {
            item.quantity = quantity;
          }

          // Recalculate totals
          const totals = calculateTotals(
            state.items,
            state.coupon,
            state.shippingMethod,
            state.giftWrap
          );

          state.subtotal = totals.subtotal;
          state.totalItems = totals.totalItems;
          state.shippingCost = totals.shippingCost;
          state.tax = totals.tax;
          state.discountAmount = totals.discountAmount;
          state.grandTotal = totals.grandTotal;
          state.totalPrice = totals.subtotal;
        });
      },

      // === Clear cart ===
      clearCart: () => {
        set((state) => {
          state.items = [];
          state.coupon = null;
          state.giftWrap = false;
          state.subtotal = 0;
          state.totalItems = 0;
          state.shippingCost = 0;
          state.tax = 0;
          state.discountAmount = 0;
          state.grandTotal = 0;
          state.totalPrice = 0;
        });
      },

      // === Apply coupon ===
      applyCoupon: async (code: string) => {
        // Simulate API call
        await new Promise((resolve) => setTimeout(resolve, 500));

        const normalizedCode = code.trim().toUpperCase();
        const coupon = VALID_COUPONS[normalizedCode];

        if (!coupon) {
          toast.error('Invalid coupon code');
          return false;
        }

        set((state) => {
          state.coupon = coupon;

          // Recalculate totals
          const totals = calculateTotals(
            state.items,
            state.coupon,
            state.shippingMethod,
            state.giftWrap
          );

          state.subtotal = totals.subtotal;
          state.totalItems = totals.totalItems;
          state.shippingCost = totals.shippingCost;
          state.tax = totals.tax;
          state.discountAmount = totals.discountAmount;
          state.grandTotal = totals.grandTotal;
          state.totalPrice = totals.subtotal;
        });

        toast.success(`Coupon ${coupon.code} applied! ${coupon.description}`);
        return true;
      },

      // === Remove coupon ===
      removeCoupon: () => {
        set((state) => {
          state.coupon = null;

          // Recalculate totals
          const totals = calculateTotals(
            state.items,
            state.coupon,
            state.shippingMethod,
            state.giftWrap
          );

          state.subtotal = totals.subtotal;
          state.totalItems = totals.totalItems;
          state.shippingCost = totals.shippingCost;
          state.tax = totals.tax;
          state.discountAmount = totals.discountAmount;
          state.grandTotal = totals.grandTotal;
          state.totalPrice = totals.subtotal;
        });

        toast.success('Coupon removed');
      },

      // === Set shipping method ===
      setShippingMethod: (method: 'standard' | 'express') => {
        set((state) => {
          state.shippingMethod = method;

          // Recalculate totals
          const totals = calculateTotals(
            state.items,
            state.coupon,
            state.shippingMethod,
            state.giftWrap
          );

          state.subtotal = totals.subtotal;
          state.totalItems = totals.totalItems;
          state.shippingCost = totals.shippingCost;
          state.tax = totals.tax;
          state.discountAmount = totals.discountAmount;
          state.grandTotal = totals.grandTotal;
          state.totalPrice = totals.subtotal;
        });
      },

      // === Toggle gift wrap ===
      toggleGiftWrap: () => {
        set((state) => {
          state.giftWrap = !state.giftWrap;

          // Recalculate totals
          const totals = calculateTotals(
            state.items,
            state.coupon,
            state.shippingMethod,
            state.giftWrap
          );

          state.subtotal = totals.subtotal;
          state.totalItems = totals.totalItems;
          state.shippingCost = totals.shippingCost;
          state.tax = totals.tax;
          state.discountAmount = totals.discountAmount;
          state.grandTotal = totals.grandTotal;
          state.totalPrice = totals.subtotal;
        });

        toast.success(get().giftWrap ? 'Gift wrap added Γ£¿' : 'Gift wrap removed');
      },

      // === Utility: Check if product is in cart ===
      isInCart: (productId: string) => {
        return get().items.some((item) => item.product.id === productId);
      },

      // === Utility: Get item quantity ===
      getItemQuantity: (productId: string) => {
        const item = get().items.find((i) => i.product.id === productId);
        return item?.quantity || 0;
      },

      // === Utility: Get item ===
      getItem: (productId: string) => {
        return get().items.find((i) => i.product.id === productId);
      },

      // === Prepare checkout data ===
      prepareCheckout: () => {
        const state = get();
        return {
          items: state.items,
          subtotal: state.subtotal,
          shippingCost: state.shippingCost,
          tax: state.tax,
          discountAmount: state.discountAmount,
          grandTotal: state.grandTotal,
          coupon: state.coupon,
          giftWrap: state.giftWrap,
          shippingMethod: state.shippingMethod,
        };
      },

      // === Reset store ===
      reset: () => {
        set(initialState);
      },
    })),
    {
      name: 'panditji-cart-storage', // Storage key
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        items: state.items,
        coupon: state.coupon,
        giftWrap: state.giftWrap,
        shippingMethod: state.shippingMethod,
      }),
      onRehydrateStorage: () => (state) => {
        if (state) {
          // Recalculate totals after rehydration
          const totals = calculateTotals(
            state.items,
            state.coupon,
            state.shippingMethod,
            state.giftWrap
          );
          state.subtotal = totals.subtotal;
          state.totalItems = totals.totalItems;
          state.shippingCost = totals.shippingCost;
          state.tax = totals.tax;
          state.discountAmount = totals.discountAmount;
          state.grandTotal = totals.grandTotal;
          state.totalPrice = totals.subtotal;
        }
      },
    }
  )
);

