// Default export
// ============================================================
export default useHomeData;

// frontend/src/features/products/hooks/useProductDetail.ts

import { useQuery, useQueries, UseQueryOptions, UseQueryResult } from '@tanstack/react-query';
import { useMemo } from 'react';
import productsApi, { productQueryKeys } from '@/features/products/api/productsApi';
import type { Product, ProductReview } from '@/features/products/types/product.types';

// ============================================================
// Types
// ============================================================
export interface UseProductDetailOptions {
  /**
   * Product slug (preferred) or ID
   */
  slug?: string;
  /**
   * Product ID (alternative to slug)
   */
  id?: string;
  /**
   * Whether to automatically fetch related products
   * @default true
   */
  fetchRelated?: boolean;
  /**
   * Whether to automatically fetch reviews
   * @default true
   */
  fetchReviews?: boolean;
  /**
   * Whether to automatically fetch availability
   * @default true
   */
  fetchAvailability?: boolean;
  /**
   * Number of related products to fetch
   * @default 6
   */
  relatedLimit?: number;
  /**
   * Number of reviews to fetch per page
   * @default 10
   */
  reviewsLimit?: number;
  /**
   * Enable/disable the query
   * @default true
   */
  enabled?: boolean;
  /**
   * Stale time in milliseconds
   * @default 5 * 60 * 1000
   */
  staleTime?: number;
  /**
   * Cache time in milliseconds
   * @default 10 * 60 * 1000
   */
  gcTime?: number;
}

export interface UseProductDetailReturn {
  /**
   * The main product data
   */
  product: Product | undefined;
  /**
   * Whether the product is loading
   */
  isLoading: boolean;
  /**
   * Whether any data is being fetched
   */
  isFetching: boolean;
  /**
   * Error object if any
   */
  error: Error | null;
  /**
   * Related products
   */
  relatedProducts: Product[] | undefined;
  /**
   * Whether related products are loading
   */
  isLoadingRelated: boolean;
  /**
   * Reviews data
   */
  reviews: {
    reviews: ProductReview[];
    total: number;
    averageRating: number;
  } | undefined;
  /**
   * Whether reviews are loading
   */
  isLoadingReviews: boolean;
  /**
   * Availability data
   */
  availability: { inStock: boolean; estimatedDelivery: string } | undefined;
  /**
   * Whether availability is loading
   */
  isLoadingAvailability: boolean;
  /**
   * Refetch the main product
   */
  refetch: () => void;
  /**
   * Refetch all data
   */
  refetchAll: () => void;
}

// ============================================================
// useProductDetail ΓÇô Combined hook
// ============================================================
/**
 * A comprehensive hook that fetches product details along with related products,
 * reviews, and availability in a single call.
 * 
 * @example
 * ```tsx
 * const { product, relatedProducts, reviews, isLoading } = useProductDetail({
 *   slug: 'ganesh-murti',
 *   fetchRelated: true,
 *   fetchReviews: true,
 * });
 * 
 * if (isLoading) return <ProductSkeleton />;
 * if (!product) return <NotFound />;
 * 
 * return (
 *   <div>
 *     <ProductDetail product={product} />
 *     <RelatedProducts products={relatedProducts} />
 *     <Reviews reviews={reviews?.reviews} />
 *   </div>
 * );
 * ```
 */
export function useProductDetail(options: UseProductDetailOptions = {}): UseProductDetailReturn {
  const {
    slug,
    id,
    fetchRelated = true,
    fetchReviews = true,
    fetchAvailability = true,
    relatedLimit = 6,
    reviewsLimit = 10,
    enabled = true,
    staleTime = 5 * 60 * 1000,
    gcTime = 10 * 60 * 1000,
  } = options;

  // Determine if we have an identifier
  const hasIdentifier = !!(slug || id);
  const isEnabled = enabled && hasIdentifier;

  // Product query key
  const productQueryKey = slug ? productQueryKeys.detail(slug) : id ? ['products', 'detail', id] : ['products', 'detail', 'invalid'];

  // 1. Main product query
  const productQuery = useQuery<Product, Error>({
    queryKey: productQueryKey,
    queryFn: async () => {
      if (slug) return productsApi.getBySlug(slug);
      if (id) return productsApi.getById(id);
      throw new Error('Either slug or id must be provided');
    },
    enabled: isEnabled,
    staleTime,
    gcTime,
    retry: 2,
  });

  const product = productQuery.data;
  const isLoading = productQuery.isLoading;
  const isFetching = productQuery.isFetching;
  const error = productQuery.error;

  // 2. Related products query (depends on product ID)
  const relatedQuery = useQuery({
    queryKey: ['products', 'related', product?.id || 'none', relatedLimit],
    queryFn: () => productsApi.getRelated(product!.id, relatedLimit),
    enabled: isEnabled && fetchRelated && !!product?.id,
    staleTime,
    gcTime,
  });

  // 3. Reviews query (depends on product ID)
  const reviewsQuery = useQuery({
    queryKey: ['products', 'reviews', product?.id || 'none', 1, reviewsLimit],
    queryFn: () => productsApi.getReviews(product!.id, 1, reviewsLimit),
    enabled: isEnabled && fetchReviews && !!product?.id,
    staleTime,
    gcTime,
  });

  // 4. Availability query (depends on product ID)
  const availabilityQuery = useQuery({
    queryKey: ['products', 'availability', product?.id || 'none'],
    queryFn: () => productsApi.checkAvailability(product!.id),
    enabled: isEnabled && fetchAvailability && !!product?.id,
    staleTime: 2 * 60 * 1000,
    gcTime: 5 * 60 * 1000,
    refetchInterval: 60 * 1000, // Refetch every minute for real-time stock
  });

  // Refetch all queries
  const refetchAll = () => {
    productQuery.refetch();
    if (fetchRelated) relatedQuery.refetch();
    if (fetchReviews) reviewsQuery.refetch();
    if (fetchAvailability) availabilityQuery.refetch();
  };

  return {
    // Main product
    product,
    isLoading,
    isFetching,
    error,
    // Related
    relatedProducts: relatedQuery.data,
    isLoadingRelated: relatedQuery.isLoading,
    // Reviews
    reviews: reviewsQuery.data,
    isLoadingReviews: reviewsQuery.isLoading,
    // Availability
    availability: availabilityQuery.data,
    isLoadingAvailability: availabilityQuery.isLoading,
    // Refetch
    refetch: productQuery.refetch,
    refetchAll,
  };
}

// ============================================================
// useProductDetailSimple ΓÇô Simplified version for basic use
// ============================================================
/**
 * A simpler version that only fetches the main product.
 * 
 * @example
 * ```tsx
 * const { product, isLoading } = useProductDetailSimple({ slug: 'ganesh-murti' });
 * ```
 */
export function useProductDetailSimple(options: {
  slug?: string;
  id?: string;
  enabled?: boolean;
  staleTime?: number;
}): UseQueryResult<Product, Error> {
  const { slug, id, enabled = true, staleTime = 5 * 60 * 1000 } = options;
  const isEnabled = enabled && !!(slug || id);

  return useQuery({
    queryKey: slug ? productQueryKeys.detail(slug) : ['products', 'detail', id || 'invalid'],
    queryFn: async () => {
      if (slug) return productsApi.getBySlug(slug);
      if (id) return productsApi.getById(id);
      throw new Error('Either slug or id must be provided');
    },
    enabled: isEnabled,
    staleTime,
    gcTime: 10 * 60 * 1000,
    retry: 2,
  });
}

// ============================================================
// useProductWithRelated ΓÇô Product + related products only
// ============================================================
export interface UseProductWithRelatedOptions {
  slug?: string;
  id?: string;
  limit?: number;
  enabled?: boolean;
}

export function useProductWithRelated(options: UseProductWithRelatedOptions = {}) {
  const { slug, id, limit = 6, enabled = true } = options;
  const hasIdentifier = !!(slug || id);
  const isEnabled = enabled && hasIdentifier;

  const productQuery = useQuery({
    queryKey: slug ? productQueryKeys.detail(slug) : ['products', 'detail', id || 'invalid'],
    queryFn: async () => {
      if (slug) return productsApi.getBySlug(slug);
      if (id) return productsApi.getById(id);
      throw new Error('Either slug or id must be provided');
    },
    enabled: isEnabled,
    staleTime: 5 * 60 * 1000,
  });

  const relatedQuery = useQuery({
    queryKey: ['products', 'related', productQuery.data?.id || 'none', limit],
    queryFn: () => productsApi.getRelated(productQuery.data!.id, limit),
    enabled: isEnabled && !!productQuery.data?.id,
    staleTime: 5 * 60 * 1000,
  });

  return {
    product: productQuery.data,
    isLoading: productQuery.isLoading || relatedQuery.isLoading,
    error: productQuery.error || relatedQuery.error,
    relatedProducts: relatedQuery.data,
    refetch: () => {
      productQuery.refetch();
      relatedQuery.refetch();
    },
  };
}

// ============================================================
// useProductReviews ΓÇô Standalone reviews hook (paginated)
// ============================================================
export interface UseProductReviewsOptions {
  productId: string;
  page?: number;
  limit?: number;
  enabled?: boolean;
}

export function useProductReviewsPaginated(options: UseProductReviewsOptions) {
  const { productId, page = 1, limit = 10, enabled = true } = options;

  return useQuery({
    queryKey: ['products', 'reviews', productId, page, limit],
    queryFn: () => productsApi.getReviews(productId, page, limit),
    enabled: enabled && !!productId,
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
  });
}

// ============================================================
// Prefetch functions for server-side rendering
// ============================================================
/**
 * Prefetch product details for SSR
 */
export async function prefetchProductDetail(
  queryClient: any,
  slug: string,
  options: { fetchRelated?: boolean; relatedLimit?: number } = {}
): Promise<void> {
  const { fetchRelated = true, relatedLimit = 6 } = options;

  // Prefetch main product
  await queryClient.prefetchQuery({
    queryKey: productQueryKeys.detail(slug),
    queryFn: () => productsApi.getBySlug(slug),
    staleTime: 5 * 60 * 1000,
  });

  // If we want related, we need the product id first ΓÇô but we don't have it yet.
  // Better to prefetch related after product is fetched (in a server component)
  // but for simplicity, we can skip or fetch using a separate call.
  // This function can be extended to use getById after fetching the product.
}

/**
 * Prefetch product by ID for SSR
 */
export async function prefetchProductById(
  queryClient: any,
  id: string,
): Promise<void> {
  await queryClient.prefetchQuery({
    queryKey: ['products', 'detail', id],
    queryFn: () => productsApi.getById(id),
    staleTime: 5 * 60 * 1000,
  });
}

// ============================================================
// Utility: Check if product data is stale
// ============================================================
export function isProductStale(product: Product, maxAgeMinutes: number = 5): boolean {
  const updated = new Date(product.updatedAt);
  const now = new Date();
  const diffMinutes = (now.getTime() - updated.getTime()) / (1000 * 60);
  return diffMinutes > maxAgeMinutes;
}

// ============================================================
// Default export
// ============================================================
export default useProductDetail;

// frontend/src/features/products/hooks/useProducts.ts

import { useQuery, useInfiniteQuery, UseQueryOptions, UseInfiniteQueryOptions, QueryKey, InfiniteData } from '@tanstack/react-query';
import { useMemo, useCallback, useState } from 'react';
import productsApi, { productQueryKeys } from '@/features/products/api/productsApi';
import type { Product, ProductFilters, ProductListResponse } from '@/features/products/types/product.types';

// ============================================================
// Types
// ============================================================
export interface UseProductsOptions {
  /**
   * Filter, sort, and pagination options
   */
  filters?: ProductFilters;
  /**
   * Enable/disable the query
   * @default true
   */
  enabled?: boolean;
  /**
   * Stale time in milliseconds
   * @default 5 * 60 * 1000 (5 minutes)
   */
  staleTime?: number;
  /**
   * Cache time in milliseconds
   * @default 10 * 60 * 1000 (10 minutes)
   */
  gcTime?: number;
  /**
   * Whether to refetch on window focus
   * @default true
   */
  refetchOnWindowFocus?: boolean;
  /**
   * Whether to refetch on reconnect
   * @default true
   */
  refetchOnReconnect?: boolean;
  /**
   * Number of items per page for infinite scroll
   * @default 12
   */
  itemsPerPage?: number;
}

export interface UseProductsReturn {
  /**
   * All products from all pages combined
   */
  products: Product[];
  /**
   * Total number of products available
   */
  totalCount: number;
  /**
   * Total number of pages
   */
  totalPages: number;
  /**
   * Fetch the next page
   */
  fetchNextPage: () => void;
  /**
   * Whether there is a next page
   */
  hasNextPage: boolean;
  /**
   * Whether the next page is being fetched
   */
  isFetchingNextPage: boolean;
  /**
   * Whether the initial data is loading
   */
  isLoading: boolean;
  /**
   * Whether the data is being refetched
   */
  isRefetching: boolean;
  /**
   * Error object if any
   */
  error: Error | null;
  /**
   * Refetch the products
   */
  refetch: () => void;
  /**
   * Reset the query
   */
  reset: () => void;
  /**
   * Filters applied
   */
  filters: ProductFilters;
  /**
   * Update filters (triggers refetch)
   */
  updateFilters: (newFilters: Partial<ProductFilters>) => void;
  /**
   * Clear all filters
   */
  clearFilters: () => void;
  /**
   * Check if any filters are active
   */
  hasActiveFilters: boolean;
  /**
   * Number of active filters
   */
  activeFilterCount: number;
}

// ============================================================
// useProducts Hook (with infinite scroll)
// ============================================================
/**
 * Custom hook for fetching products with infinite scroll and filtering.
 * 
 * @example
 * ```tsx
 * const { products, isLoading, hasNextPage, fetchNextPage } = useProducts({
 *   filters: { category: 'ganesh', sort: 'price-asc' },
 *   itemsPerPage: 12,
 * });
 * 
 * // In your component
 * <div>
 *   {products.map(product => <ProductCard key={product.id} product={product} />)}
 *   {hasNextPage && <button onClick={fetchNextPage}>Load More</button>}
 * </div>
 * ```
 */
export function useProducts(options: UseProductsOptions = {}): UseProductsReturn {
  const {
    filters = {},
    enabled = true,
    staleTime = 5 * 60 * 1000,
    gcTime = 10 * 60 * 1000,
    refetchOnWindowFocus = true,
    refetchOnReconnect = true,
    itemsPerPage = 12,
  } = options;

  // Build query key from filters
  const queryKey = useMemo(() => {
    return productQueryKeys.list(filters);
  }, [filters]);

  // Use infinite query for pagination
  const {
    data,
    isLoading,
    isFetchingNextPage,
    isRefetching,
    hasNextPage,
    fetchNextPage,
    error,
    refetch,
  } = useInfiniteQuery<ProductListResponse, Error, InfiniteData<ProductListResponse>, QueryKey, number>({
    queryKey,
    queryFn: ({ pageParam }) => {
      return productsApi.getAll({
        ...filters,
        page: pageParam,
        limit: itemsPerPage,
      });
    },
    initialPageParam: 1,
    getNextPageParam: (lastPage) => {
      const { page, totalPages } = lastPage;
      return page < totalPages ? page + 1 : undefined;
    },
    enabled,
    staleTime,
    gcTime,
    refetchOnWindowFocus,
    refetchOnReconnect,
  });

  // Extract products from all pages
  const products = useMemo(() => {
    return data?.pages.flatMap((page) => page.products) ?? [];
  }, [data]);

  // Get total count from first page
  const totalCount = data?.pages[0]?.total ?? 0;
  const totalPages = data?.pages[0]?.totalPages ?? 0;

  // Filter management
  const hasActiveFilters = useMemo(() => {
    return Object.values(filters).some((value) => {
      if (Array.isArray(value)) return value.length > 0;
      if (typeof value === 'boolean') return value === true;
      if (typeof value === 'number') return value > 0;
      return !!value;
    });
  }, [filters]);

  const activeFilterCount = useMemo(() => {
    let count = 0;
    const filterKeys = Object.keys(filters) as (keyof ProductFilters)[];
    for (const key of filterKeys) {
      const value = filters[key];
      if (Array.isArray(value) && value.length > 0) count++;
      else if (value && !Array.isArray(value)) count++;
    }
    return count;
  }, [filters]);

  // Update filters function
  const updateFilters = useCallback((newFilters: Partial<ProductFilters>) => {
    // Create new filters object (immutable)
    const updatedFilters = { ...filters, ...newFilters };
    // Trigger refetch with new filters
    refetch();
    // Return updated filters for callers
  }, [filters, refetch]);

  // Clear all filters
  const clearFilters = useCallback(() => {
    updateFilters({
      category: undefined,
      subCategory: undefined,
      search: undefined,
      minPrice: undefined,
      maxPrice: undefined,
      material: undefined,
      colors: undefined,
      height: undefined,
      weight: undefined,
      inStock: undefined,
      isFeatured: undefined,
      isNew: undefined,
      rating: undefined,
      tags: undefined,
      sort: 'newest',
    });
  }, [updateFilters]);

  // Reset the query
  const reset = useCallback(() => {
    // This will reset the query state
    refetch();
  }, [refetch]);

  return {
    products,
    totalCount,
    totalPages,
    fetchNextPage,
    hasNextPage: !!hasNextPage,
    isFetchingNextPage,
    isLoading,
    isRefetching,
    error,
    refetch,
    reset,
    filters,
    updateFilters,
    clearFilters,
    hasActiveFilters,
    activeFilterCount,
  };
}

// ============================================================
// useProduct ΓÇô Single product hook
// ============================================================
export interface UseProductOptions extends UseQueryOptions<Product, Error> {
  slug?: string;
  id?: string;
  enabled?: boolean;
}

/**
 * Hook for fetching a single product by slug or ID
 * 
 * @example
 * ```tsx
 * const { data: product, isLoading } = useProduct({ slug: 'ganesh-murti' });
 * ```
 */
export function useProduct({ 
  slug, 
  id, 
  enabled = true, 
  queryKey: _queryKey,
  ...options 
}: UseProductOptions) {
  const isEnabled = enabled && !!(slug || id);
  const queryKey = slug 
    ? productQueryKeys.detail(slug)
    : id 
    ? ['products', 'detail', id] as QueryKey
    : ['products', 'detail', 'invalid'] as QueryKey;

  const queryFn = async () => {
    if (slug) return productsApi.getBySlug(slug);
    if (id) return productsApi.getById(id);
    throw new Error('Either slug or id must be provided');
  };

  const query = useQuery<Product, Error>({
    queryKey,
    queryFn,
    enabled: isEnabled,
    staleTime: 5 * 60 * 1000,
    gcTime: 10 * 60 * 1000,
    retry: 2,
    ...options,
  });

  return query;
}

