  originalPrice?: number;
  
  /** Discount percentage (derived from originalPrice/price, but some UIs read it directly) */
  discount?: number;
  
  /** Array of product image URLs */
  images: string[];
  
  /** Array of 360-degree view image URLs (optional) */
  images360?: string[];
  
  /** Product video URL (optional) */
  videoUrl?: string;
  
  /** Material used (e.g., 'Marble', 'Brass', 'Wood') */
  material?: string;
  
  /** Type of marble used (e.g., 'Makrana', 'White', 'Pink') */
  marbleType?: string;
  
  /** Finish type (e.g., 'Polished', 'Matte', 'Antique') */
  finish?: string;
  
  /** Available colors */
  colors?: string[];
  
  /** Product category ID */
  category: string;
  
  /** Product category name */
  categoryName?: string;
  
  /** Product sub-category ID */
  subCategory?: string;
  
  /** Product tags for filtering */
  tags?: string[];
  
  /** Height in centimeters */
  height?: number;
  
  /** Width in centimeters */
  width?: number;
  
  /** Depth in centimeters */
  depth?: number;
  
  /** Weight in kilograms */
  weight?: number;
  
  /** Whether the product is in stock */
  inStock: boolean;
  
  /** Current stock quantity */
  stockQuantity?: number;
  
  /** Whether the product is featured */
  isFeatured?: boolean;
  
  /** Whether the product is new */
  isNew?: boolean;
  
  /** Whether the product is on sale */
  isOnSale?: boolean;
  
  /** Average rating (1-5) */
  rating?: number;
  
  /** Number of reviews */
  reviewCount?: number;
  
  /** Estimated delivery time in days */
  estimatedDelivery?: string;
  
  /** SKU (Stock Keeping Unit) */
  sku?: string;
  
  /** GST rate applied to the product */
  gstRate?: number;
  
  /** Handcrafted details/notes */
  handcraftedDetails?: string;
  
  /** Product specifications */
  specifications?: ProductSpecification[];
  
  /** Product variants (if any) */
  variants?: ProductVariant[];
  
  /** Related product IDs */
  relatedProductIds?: string[];
  
  /** Creation timestamp */
  createdAt: string;
  
  /** Last update timestamp */
  updatedAt: string;
  
  /** Whether the product is active */
  isActive?: boolean;
  
  /** SEO metadata */
  seo?: ProductSEO;
}

/**
 * Product specifications (key-value pairs with display order)
